export const LINEA_AEREA_OFICIAL: LineaAereaOficialQuestion[] = [
  { id: "q_laof_1_001", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LFT", text: "De acuerdo con el artículo 223 de la LFT, ¿Cuál es el tiempo total de servicios que pueden prestar los tripulantes?", options: ["90 horas mensuales.", "180 horas mensuales.", "30 horas mensuales."], correctIndex: 1, explanation: "El artículo 223 de la LFT dispone que el tiempo total de servicios (tiempo efectivo de vuelo, de ruta y servicios de reserva) se fijará en el contrato de trabajo 'sin que pueda exceder de ciento ochenta horas mensuales'. Las 90 horas del distractor corresponden al tiempo efectivo de vuelo del artículo 224, no al tiempo total de servicios.", cite: "LFT Art. 223" },
  { id: "q_laof_1_002", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LFT", text: "De acuerdo con el artículo 224 de la LFT, ¿Cuál es el tiempo efectivo de vuelo que pueden trabajar los tripulantes?", options: ["30 horas mensuales.", "180 horas mensuales.", "90 horas mensuales."], correctIndex: 2, explanation: "El artículo 224 de la LFT limita el tiempo efectivo de vuelo mensual 'sin que pueda exceder de noventa horas'. Las 180 horas son el límite del tiempo total de servicios (Art. 223), un concepto distinto que incluye tiempo de ruta y reservas.", cite: "LFT Art. 224" },
  { id: "q_laof_1_003", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LFT", text: "¿Cuál es el período anual de vacaciones anual no acumulable a que hace mención el artículo 233 de la LFT?", options: ["60 días de calendario, acumulables.", "7 días por año de servicio prestado.", "30 días de calendario, no acumulables."], correctIndex: 2, explanation: "El artículo 233 de la LFT otorga a los tripulantes 'un período anual de vacaciones de treinta días de calendario, no acumulables', que aumenta un día por cada año de servicios sin exceder de sesenta días. Los 60 días del distractor son el tope máximo por antigüedad, no el período base, y además el artículo señala expresamente que no son acumulables.", cite: "LFT Art. 233" },
  { id: "q_laof_1_004", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LFT", text: "De acuerdo con el artículo 237 de la LFT, los tripulantes tienen la siguiente obligación…", options: ["Conservar en vigor sus licencias, pasaportes, visas y documentos que se requieran legalmente para el desempeño de su trabajo.", "De ausentarse al desempeño de sus funciones cuando las condiciones de meteorología prescriban la realización de las operaciones.", "De notificar a la Secretaría, por conducto de la autoridad aeronáutica local cuando se esté próximo al cumplimiento legal de los tiempos de jornada prescritos en la ley."], correctIndex: 0, explanation: "La fracción II del artículo 237 de la LFT obliga a los tripulantes a 'conservar en vigor sus licencias, pasaportes, visas y documentos que se requieran legalmente para el desempeño de su trabajo'. Las otras dos opciones (ausentarse por meteorología o notificar a la Secretaría por jornadas) no figuran en ninguna fracción del artículo 237.", cite: "LFT Art. 237, fracción II" },
  { id: "q_laof_1_005", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LFT", text: "De acuerdo con el artículo 237 de la LFT, es obligación del tripulante el efectuar vuelos de auxilio, búsqueda y salvamento en cualquier tiempo y lugar que se requiera…", options: ["Cierto.", "Falso.", "No se especifica nada en la ley."], correctIndex: 0, explanation: "Cierto. La fracción X del artículo 237 de la LFT ordena 'efectuar vuelos de auxilio, búsqueda o salvamento en cualquier tiempo y lugar que se requiera'. Tan vinculante es la obligación que la negativa injustificada a ejecutar estos vuelos es causa especial de rescisión (LFT Art. 244, fracción V).", cite: "LFT Art. 237, fracción X" },
  { id: "q_laof_1_006", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LFT", text: "De acuerdo con el artículo 242 de la LFT, queda prohibido a los tripulantes…", options: ["Ingerir bebidas alcohólicas durante la prestación del servicio y en las veinticuatro horas anteriores a la iniciación de los vuelos que tenga asignados.", "Ingerir bebidas alcohólicas en las ocho horas anteriores a la iniciación de los vuelos asignados.", "Ingerir bebidas alcohólicas en las doce horas anteriores a un servicio de todo tipo."], correctIndex: 0, explanation: "La fracción I del artículo 242 de la LFT prohíbe 'ingerir bebidas alcohólicas durante la prestación del servicio y en las veinticuatro horas anteriores a la iniciación de los vuelos que tengan asignados'. Los plazos de ocho y doce horas de los distractores no existen en la LFT.", cite: "LFT Art. 242, fracción I" },
  { id: "q_laof_1_007", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LFT", text: "De acuerdo con el artículo 244 de la LFT, son causas especiales de terminación o rescisión de las relaciones de trabajo…", options: ["Encontrarse en estado de embriaguez, dentro de las veinticuatro horas anteriores a la iniciación del vuelo que tenga asignado o durante el transcurso del mismo.", "Encontrarse en estado de embriaguez, dentro de las doce horas anteriores a la iniciación del vuelo que tenga asignado o durante el transcurso del mismo.", "Encontrarse en estado de embriaguez, dentro de las ocho horas anteriores a la iniciación del vuelo que tenga asignado o durante el transcurso del mismo."], correctIndex: 0, explanation: "La fracción II del artículo 244 de la LFT establece como causa especial de terminación o rescisión 'encontrarse el tripulante en estado de embriaguez, dentro de las veinticuatro horas anteriores a la iniciación del vuelo que tenga asignado o durante el transcurso del mismo'. Los plazos de doce y ocho horas carecen de sustento legal.", cite: "LFT Art. 244, fracción II" },
  { id: "q_laof_1_008", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "De acuerdo con el artículo 3º de la LAC, la explotación, uso o aprovechamiento del espacio aéreo situado sobre el territorio nacional es de jurisdicción…", options: ["Federal.", "Estatal.", "Local."], correctIndex: 0, explanation: "El artículo 3 de la LAC es literal: 'La explotación, uso o aprovechamiento del espacio aéreo situado sobre el territorio nacional, es de jurisdicción federal'. Las jurisdicciones estatal y local no tienen competencia alguna sobre el espacio aéreo.", cite: "LAC Art. 3" },
  { id: "q_laof_1_009", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "De acuerdo con el artículo 3º de la LAC, si ocurre un hecho jurídico en una aeronave filipina sobre territorio nacional mexicano, el mismo se ve sujeto a las leyes de…", options: ["Filipinas.", "Indistinto al ser miembros contratantes de OACI.", "México."], correctIndex: 0, explanation: "El propio artículo 3 de la LAC dispone que los hechos ocurridos a bordo de una aeronave civil extranjera durante su vuelo sobre territorio nacional 'se regirán por las leyes y autoridades del Estado de matrícula de la aeronave', sin perjuicio de los tratados; por ello aplican las leyes de Filipinas. 'México' es el distractor principal: la ley mexicana solo rige a bordo de aeronaves de matrícula mexicana, y en caso de delitos se estará al Código Penal Federal.", cite: "LAC Art. 3, párrafo segundo" },
  { id: "q_laof_1_010", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "De acuerdo con la LAC, un reporte de incapacitación en vuelo debe ser realizado…", options: ["Dentro de las veinticuatro horas siguientes al suceso, con exclusión del día hábil en que ocurre.", "Dentro de las veinticuatro horas siguientes al suceso, con exclusión del día natural en que ocurre.", "Dentro de las veinticuatro horas siguientes al suceso."], correctIndex: 2, explanation: "El artículo 34 Ter de la LAC ordena realizar los reportes de incapacitación en vuelo 'dentro de las veinticuatro horas siguientes al suceso', sin más. Las exclusiones de 'día hábil' o 'día natural' de los distractores son agregados que no existen en el texto legal.", cite: "LAC Art. 34 Ter" },
  { id: "q_laof_1_011", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "¿A través de qué entidad la Secretaría ejerce autoridad aeronáutica en los aeropuertos y aeródromos en general? (Art. 7)", options: ["De Aeropuertos y Servicios Auxiliares.", "De la Secretaría de la Defensa Nacional.", "De la Agencia Federal de Aviación Civil."], correctIndex: 2, explanation: "Conforme al artículo 7 de la LAC, es la Agencia Federal de Aviación Civil la que ejerce la autoridad en los aeropuertos, helipuertos y aeródromos en general (a través de comandantes regionales y de aeropuerto). Aeropuertos y Servicios Auxiliares es un organismo operador de aeropuertos y la SEDENA no ejerce la autoridad aeronáutica civil.", cite: "LAC Art. 7" },
  { id: "q_laof_1_012", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "¿Qué declaración es cierta de acuerdo con el artículo 33 de la LAC?", options: ["En las aeronaves civiles no podrán abordar personas armadas a menos que sean miembros de las fuerzas armadas en funciones oficiales.", "En las aeronaves civiles no podrán abordar personas armadas, en estado de ebriedad o bajo el influjo de estupefacientes…", "En las aeronaves civiles podrán abordar personas armadas siempre y cuando los dispositivos de detonación se encuentren inhabilitados y bajo previo registro."], correctIndex: 1, explanation: "El artículo 33 de la LAC establece: 'En las aeronaves civiles no podrán abordar personas armadas, en estado de ebriedad o bajo el influjo de estupefacientes, psicotrópicos o enervantes'. La ley no contempla la excepción para miembros de las fuerzas armadas ni la de armas con dispositivos inhabilitados que plantean los distractores.", cite: "LAC Art. 33" },
  { id: "q_laof_1_013", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "De acuerdo con el artículo 40º de la LAC, toda aeronave deberá contar con un comandante o piloto al mando…", options: ["Cierto.", "Falso."], correctIndex: 0, explanation: "Cierto. El primer párrafo del artículo 40 de la LAC dispone: 'Toda aeronave deberá contar con un comandante o piloto al mando, quien será la máxima autoridad a bordo y el responsable de su operación y dirección y de mantener el orden y la seguridad de la aeronave, de los tripulantes, pasajeros, equipaje, carga y correo'.", cite: "LAC Art. 40" },
  { id: "q_laof_1_014", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "De acuerdo con el artículo 40º de la LAC, el comandante de las aeronaves de servicio al público deberá ser mexicano por nacimiento…", options: ["Cierto.", "Falso."], correctIndex: 0, explanation: "Cierto. El artículo 40 de la LAC señala: 'El comandante de las aeronaves de servicio al público deberá ser mexicano por nacimiento que no adquiera otra nacionalidad y estar en pleno goce y ejercicio de sus derechos civiles y políticos'.", cite: "LAC Art. 40" },
  { id: "q_laof_1_015", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "De acuerdo con el artículo 40º de la LAC, en caso de emergencia o por razones de seguridad, el comandante o el piloto que lo sustituya actuará en nombre de quien lo designó y tomará las decisiones pertinentes…", options: ["Cierto.", "Falso."], correctIndex: 0, explanation: "Cierto. El artículo 40 de la LAC establece textualmente: 'En casos de emergencia o por razones de seguridad, el comandante o el piloto que lo sustituya actuará en nombre de quien lo designó y tomará las decisiones pertinentes'.", cite: "LAC Art. 40" },
  { id: "q_laof_1_016", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "De acuerdo con el artículo 40º de la LAC, toda persona a bordo está obligada a acatar las instrucciones del comandante para la seguridad y operación de la aeronave…", options: ["Cierto.", "Falso."], correctIndex: 0, explanation: "Cierto. El artículo 40 de la LAC dispone: 'Toda persona a bordo está obligada a acatar las instrucciones del comandante para la seguridad y operación de la aeronave'.", cite: "LAC Art. 40" },
  { id: "q_laof_1_017", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "De acuerdo con el artículo 40º de la LAC, el comandante registrará en el libro de bitácora los hechos que puedan tener consecuencias legales, ocurridos durante el vuelo…", options: ["Cierto.", "Falso."], correctIndex: 0, explanation: "Cierto. El artículo 40 de la LAC señala que 'el comandante registrará en el libro de bitácora los hechos que puedan tener consecuencias legales, ocurridos durante el vuelo', y los pondrá en conocimiento de las autoridades competentes del primer lugar de aterrizaje (o del cónsul mexicano en el extranjero).", cite: "LAC Art. 40" },
  { id: "q_laof_1_018", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "LAC", text: "Para efectos de la LAC, se entiende por accidente… (escoja el pronunciamiento más correcto).", options: ["Todo suceso por el que se cause la muerte o lesiones graves a personas a bordo de la aeronave o bien, se ocasionen daños o roturas estructurales a la aeronave, o por el que la aeronave desaparezca o se encuentre en un lugar inaccesible.", "Todo suceso por el que se cause la muerte o lesiones graves a personas, indistintamente si se encuentran a bordo de la aeronave o no, o bien, se ocasionen daños o roturas estructurales a la aeronave, o por el que la aeronave desaparezca o se encuentre en un lugar inaccesible.", "Todo suceso por el que se causen indisposiciones de salud de cualquier tipo o bien, se ocasionen daños o roturas estructurales a la aeronave, o por el que la aeronave desaparezca o se encuentre en un lugar inaccesible."], correctIndex: 0, explanation: "El artículo 79, fracción I de la LAC define accidente como 'todo suceso por el que se cause la muerte o lesiones graves a personas a bordo de la aeronave o bien, se ocasionen daños o roturas estructurales a la aeronave, o por el que la aeronave desaparezca o se encuentre en un lugar inaccesible'. El distractor B extiende la definición a personas fuera de la aeronave (criterio más cercano al Anexo 13 de la OACI), pero la LAC la limita expresamente a personas a bordo.", cite: "LAC Art. 79, fracción I" },
  { id: "q_laof_1_019", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "RLAC", text: "De acuerdo con el artículo 43 del RLAC ¿Qué puede hacerse si un pasajero se rehúsa a una revisión de seguridad?", options: ["Solicitar la intervención de la autoridad competente.", "Si se invoca la protección de una Comisión o entidad de Derechos Humanos, permitírsele el acceso a zonas restringidas o estériles.", "Someterle a arresto federal hasta por 36 horas en zonas designadas en el recinto aeroportuario."], correctIndex: 0, explanation: "El artículo 43 del RLAC prevé que 'en caso de que el pasajero rehúse la revisión, se puede solicitar la intervención de la autoridad competente para que la efectúe'. El RLAC no permite el acceso a zonas restringidas invocando protección de derechos humanos ni contempla arresto federal de 36 horas.", cite: "RLAC Art. 43" },
  { id: "q_laof_1_020", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "RLAC", text: "De acuerdo con el artículo 43 del RLAC, ¿Se puede solicitar la intervención de la autoridad competente en el caso que un pasajero se rehúse a ser revisado?", options: ["No, porque la libertad de tránsito es una garantía constitucional.", "No, porque existe contraposición a la Declaración Universal de los Derechos Humanos.", "Sí."], correctIndex: 2, explanation: "Sí. El artículo 43 del RLAC lo autoriza expresamente: si el pasajero rehúsa la revisión 'se puede solicitar la intervención de la autoridad competente para que la efectúe'. Los distractores invocan la libertad de tránsito y la Declaración Universal de Derechos Humanos, argumentos que el reglamento no recoge frente a la revisión de seguridad.", cite: "RLAC Art. 43" },
  { id: "q_laof_1_021", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "RLAC", text: "De acuerdo con el artículo 77 del RLAC, ¿Cómo se integra el personal de vuelo?", options: ["En tripulación comisionada al servicio y en no comisionada al servicio.", "En tripulación en funciones y tripulación en servicio de traslado.", "En tripulación de vuelo y tripulación de sobrecargos."], correctIndex: 2, explanation: "El artículo 77 del RLAC es literal: 'El personal de vuelo está formado por la tripulación de vuelo y la tripulación de sobrecargos'. Las clasificaciones de 'comisionada/no comisionada' o 'en funciones/en traslado' no existen en el reglamento.", cite: "RLAC Art. 77" },
  { id: "q_laof_1_022", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "RLAC", text: "¿Cómo define el artículo 79 del RLAC a la tripulación de vuelo?", options: ["Aquella que tiene a su cargo funciones de servicio durante el tiempo de vuelo, de conformidad con las normas oficiales mexicanas correspondientes.", "Aquella que tiene a su cargo funciones no esenciales para la operación de la aeronave durante el tiempo de vuelo, de conformidad con las normas oficiales mexicanas correspondientes.", "Aquella que tiene a su cargo funciones esenciales para la operación de la aeronave durante el tiempo de vuelo, de conformidad con las normas oficiales mexicanas correspondientes."], correctIndex: 2, explanation: "El artículo 79 del RLAC define que 'la tripulación de vuelo tiene a su cargo funciones esenciales para la operación de la aeronave durante el tiempo de vuelo de conformidad con las normas oficiales mexicanas correspondientes'. El distractor B invierte el sentido al decir 'no esenciales' y el A habla de 'funciones de servicio', propias de los sobrecargos.", cite: "RLAC Art. 79" },
  { id: "q_laof_1_023", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "RLAC", text: "¿Qué restricción impone el artículo 82 del RLAC respecto a las horas de vuelo?", options: ["No poder volar más de treinta horas durante cinco días consecutivos.", "No poder volar más de noventa horas durante treinta días consecutivos ni más de mil horas al año.", "No poder volar más de treinta horas durante seis días consecutivos."], correctIndex: 1, explanation: "El artículo 82 del RLAC dispone que los integrantes de las tripulaciones 'no pueden volar más de noventa horas durante un período de treinta días naturales consecutivos, ni más de un mil horas durante un período de trescientos sesenta y cinco días naturales consecutivos'. El límite corto real es de treinta horas en siete días naturales consecutivos, por lo que los distractores de cinco y seis días son falsos.", cite: "RLAC Art. 82" },
  { id: "q_laof_1_024", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "RLAC", text: "¿Qué restricción impone el artículo 82 del RLAC respecto a volar más de 8:30 horas durante las últimas 24 horas?", options: ["Recibir 24 horas de descanso antes que se asigne otro servicio.", "Recibir el descanso mínimo contractual de no menor a 12 horas antes que se asigne otro servicio.", "Recibir 36 horas de descanso antes que se asigne otro servicio, para el caso de vuelos nocturnos."], correctIndex: 0, explanation: "El artículo 82 del RLAC establece que quienes 'hayan volado más de ocho horas y treinta minutos durante un período de veinticuatro horas, deben recibir veinticuatro horas de descanso antes de que se les asigne otro servicio'. Los descansos de 12 o 36 horas de los distractores no figuran en el reglamento.", cite: "RLAC Art. 82" },
  { id: "q_laof_1_025", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "RLAC", text: "De acuerdo con el artículo 85 del RLAC, ¿Cuál es la función principal de la tripulación de sobrecargos?", options: ["Auxiliar al operador en la provisión de los estándares de servicio a pasajeros que considere adecuados.", "Auxiliar a la Secretaría en el cumplimiento de las normas relativas a seguridad operacional.", "Auxiliar al comandante en el cumplimiento de las disposiciones en materia de seguridad y emergencia en la cabina de pasajeros durante la operación del vuelo."], correctIndex: 2, explanation: "El artículo 85 del RLAC señala que la tripulación de sobrecargos 'tiene como principal función auxiliar a las personas comandante o piloto que se encuentren al mando de la aeronave en el cumplimiento de las disposiciones en materia de seguridad y emergencia en la cabina de personas pasajeras durante la operación del vuelo'. El servicio a pasajeros es función adicional, no la principal, y no se auxilia a la Secretaría.", cite: "RLAC Art. 85" },
  { id: "q_laof_1_026", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "RLAC", text: "De acuerdo con el artículo 86 del RLAC, ¿Qué número mínimo de sobrecargos se requiere en cada aeronave?", options: ["Para aeronaves de veinte a cincuenta pasajeros un sobrecargo; para aeronaves de cincuenta y uno a cien pasajeros dos sobrecargos y para aeronaves de más de cien pasajeros un sobrecargo más por cada cincuenta adicionales.", "Las recomendadas o contempladas en el manual de operaciones del fabricante.", "Un sobrecargo por cada cincuenta asientos instalados."], correctIndex: 0, explanation: "El artículo 86 del RLAC fija el mínimo: un sobrecargo para aeronaves de veinte a cincuenta pasajeros (fr. I); dos para aeronaves de cincuenta y uno a cien (fr. II); y un sobrecargo más por cada cincuenta pasajeros adicionales en aeronaves de más de cien (fr. III). No se remite al manual del fabricante ni existe la regla de 'uno por cada cincuenta asientos instalados'.", cite: "RLAC Art. 86" },
  { id: "q_laof_1_027", fuente: LA_OFICIAL_FUENTE, materia: "legislacion", tema: "RLAC", text: "¿Qué establece el artículo 111 del RLAC respecto a la manipulación de controles?", options: ["Solo bajo autorización del operador es que personas extrañas a los miembros de la tripulación de vuelo se les permite hacer uso de los controles de la aeronave en vuelo.", "Solo cuando sea requerido para evitar actos contra interferencia ilícita la tripulación de sobrecargos puede ocupar las estaciones designadas a la tripulación de vuelo.", "Ninguna persona extraña a los miembros de la tripulación de vuelo puede hacer uso de los controles de la aeronave en vuelo."], correctIndex: 2, explanation: "El artículo 111 del RLAC ordena que 'ninguna persona extraña al personal de la tripulación de vuelo puede hacer uso de los controles de la aeronave en vuelo'. La autorización del operador o de la AFAC solo permite pasar a la cabina de mando y ocupar asientos adicionales, nunca manipular los controles.", cite: "RLAC Art. 111" },
  { id: "q_laof_1_028", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "¿En cuánto tiempo se completa un viraje de 360° con un viraje estándar?", options: ["En dos minutos.", "En cuatro minutos.", "En un minuto."], correctIndex: 0, explanation: "Un viraje estándar (standard rate) se define como un régimen de 3° por segundo, por lo que 360° se completan en 120 segundos, es decir, dos minutos. Los cuatro minutos del distractor corresponden al medio régimen (1.5°/s) usado por aeronaves de alta velocidad.", cite: "PHAK Cap. 8 (turn coordinator) y glosario" },
  { id: "q_laof_1_029", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "¿Qué es RNAV?", options: ["Un método de navegación que permite a las aeronaves operar en cualquier dirección con cobertura de señales provenientes de estaciones, equipos autónomos integrales a bordo o una combinación de éstos.", "Un método de navegación que para la determinación de la posición de una aeronave usa exclusivamente la interpretación de señales de estaciones de radio terrestres.", "Un conjunto de reglas que permiten la operación de las aeronaves con reducido espaciamiento vertical."], correctIndex: 0, explanation: "RNAV (navegación de área) es el método que permite operar en cualquier trayectoria deseada dentro de la cobertura de ayudas referidas a estaciones, dentro de la capacidad de equipos autónomos a bordo, o una combinación de ambos (definición OACI). El distractor B describe la radionavegación convencional de estación a estación y el C describe RVSM.", cite: "PHAK Cap. 16 / definición OACI de RNAV" },
  { id: "q_laof_1_030", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Por su intensidad, ¿cómo se clasifican las turbulencias?", options: ["Ocasional, intermitente y continua.", "Baja, media y alta.", "Ligera, moderada, severa y extrema."], correctIndex: 2, explanation: "Por su intensidad, la turbulencia se clasifica en ligera, moderada, severa y extrema, escala usada en los reportes de piloto (PIREP) y publicaciones meteorológicas aeronáuticas. 'Ocasional, intermitente y continua' describe la frecuencia, no la intensidad.", cite: "PHAK Cap. 13 / AIM 7-1-21" },
  { id: "q_laof_1_031", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué es el punto de rocío?", options: ["La temperatura a la que el aire es más seco.", "La temperatura a la que el aire alcanza el 100% de humedad.", "La hora del día en que aparece humedad visible en la superficie terrestre."], correctIndex: 1, explanation: "El punto de rocío es la temperatura a la cual el aire debe enfriarse para saturarse, es decir, alcanzar el 100% de humedad relativa; al llegar a ella se condensa humedad visible. No es una hora del día ni la temperatura de aire más seco.", cite: "PHAK Cap. 12" },
  { id: "q_laof_1_032", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué son las líneas isobáricas?", options: ["Son líneas graficadas en cartas que representan y unen zonas de igual humedad.", "Son líneas graficadas en cartas que representan y unen zonas de igual temperatura.", "Son líneas graficadas en cartas que representan y unen zonas de igual presión barométrica."], correctIndex: 2, explanation: "Las isobaras son líneas que en las cartas meteorológicas unen puntos de igual presión barométrica. Las líneas de igual temperatura son las isotermas, y las de igual humedad no son las isobaras.", cite: "PHAK Cap. 12" },
  { id: "q_laof_1_033", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿En cuántos fragmentos se divide la bóveda celeste para determinar la cobertura del cielo?", options: ["En cinco partes (pentas).", "En seis partes (sextas).", "En ocho partes (octas)."], correctIndex: 2, explanation: "La cobertura del cielo se reporta dividiendo la bóveda celeste en ocho partes u octas (eighths). De ahí derivan las claves FEW (1-2/8), SCT (3-4/8), BKN (5-7/8) y OVC (8/8).", cite: "PHAK Cap. 13" },
  { id: "q_laof_1_034", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué significado tiene OVC?", options: ["Cerrado.", "Medio nublado.", "Nublado alto."], correctIndex: 0, explanation: "OVC (overcast) significa cielo cerrado o cubierto: la capa cubre 8/8 de la bóveda celeste. 'Medio nublado' correspondería a SCT/BKN y 'nublado alto' no es una clave de cobertura.", cite: "PHAK Cap. 13" },
  { id: "q_laof_1_035", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué significa SKC?", options: ["Nublado por Cirrus.", "Parcialmente nublado.", "Cielo despejado."], correctIndex: 2, explanation: "SKC (sky clear) significa cielo despejado, sin capas de nubes reportadas. No guarda relación con nubes cirrus ni con cobertura parcial.", cite: "PHAK Cap. 13" },
  { id: "q_laof_1_036", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué cobertura del cielo indica FEW?", options: ["1/8 a 2/8.", "1/2 a 3/4.", "1/3 a 2/3."], correctIndex: 0, explanation: "FEW indica una cobertura de 1/8 a 2/8 de la bóveda celeste. Las demás fracciones no corresponden a la clave: SCT es 3/8-4/8, BKN 5/8-7/8 y OVC 8/8.", cite: "PHAK Cap. 13" },
  { id: "q_laof_1_037", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué cobertura del cielo indica SCT?", options: ["3/8 a 4/8.", "2/4 a 3/4.", "1/3 a 2/3."], correctIndex: 0, explanation: "SCT (scattered) indica una cobertura de 3/8 a 4/8 de la bóveda celeste. Las opciones en cuartos y tercios no corresponden al sistema de octas con que se reporta la cobertura.", cite: "PHAK Cap. 13" },
  { id: "q_laof_1_038", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué cobertura del cielo indica BKN?", options: ["2/3 a 3/3.", "2/4 a 3/4.", "5/8 a 7/8."], correctIndex: 2, explanation: "BKN (broken) indica una cobertura de 5/8 a 7/8; el PHAK lo define textualmente como 'broken when five-eighths to seven-eighths of the sky is covered'. Las opciones en tercios y cuartos no corresponden al sistema de octas.", cite: "PHAK Cap. 13" },
  { id: "q_laof_1_039", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué cobertura del cielo indica OVC?", options: ["8/8.", "3/4 a 4/4.", "1/2 a 2/3."], correctIndex: 0, explanation: "OVC (overcast) indica cielo completamente cubierto: 8/8 de la bóveda celeste. Cualquier fracción menor corresponde a BKN, SCT o FEW.", cite: "PHAK Cap. 13" },
  { id: "q_laof_1_040", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "Para una aeronave en vuelo, ¿qué significa que se le dirija desde el control del aeródromo una luz verde fija?", options: ["Continúe en ruta hacia su destino.", "Autorizado a aterrizar.", "Ceda el paso a aeronave que precede."], correctIndex: 1, explanation: "Para una aeronave en vuelo, la luz verde fija significa 'autorizado a aterrizar' (cleared to land), conforme a la tabla de señales luminosas de ATC. 'Continúe en ruta' no es una señal luminosa estándar y 'ceda el paso' corresponde a la roja fija.", cite: "PHAK Cap. 14, Fig. 14-42 (light gun signals)" },
  { id: "q_laof_1_041", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "Para una aeronave en vuelo, ¿qué significa que se le dirija desde el control del aeródromo una luz roja fija?", options: ["No aterrice, aeródromo inseguro.", "Ceda el paso a otras aeronaves y continúe circulando.", "Regrese a aterrizar."], correctIndex: 1, explanation: "Para una aeronave en vuelo, la luz roja fija significa 'ceda el paso a otras aeronaves y continúe circulando' (give way to other aircraft and continue circling). 'No aterrice, aeródromo inseguro' es la roja destellante y 'regrese a aterrizar' es la verde destellante.", cite: "PHAK Cap. 14, Fig. 14-42 (light gun signals)" },
  { id: "q_laof_1_042", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "Para una aeronave en vuelo, ¿qué significa que se le dirija desde el control del aeródromo una luz verde destellante?", options: ["Aterrice en este aeródromo y proceda a la rampa/plataforma.", "Autorizado a aterrizar.", "Regrese a aterrizar (se provee posteriormente de autorización de aterrizaje)."], correctIndex: 2, explanation: "Para una aeronave en vuelo, la luz verde destellante significa 'regrese para aterrizar', y será seguida de verde fija en el momento oportuno como autorización de aterrizaje. 'Autorizado a aterrizar' corresponde a la verde fija, no a la destellante.", cite: "PHAK Cap. 14, Fig. 14-42 (light gun signals)" },
  { id: "q_laof_1_043", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "Para una aeronave en vuelo, ¿qué significa que se le dirija desde el control del aeródromo una luz roja destellante?", options: ["Ceda el paso a otras aeronaves y continúe circulando.", "No aterrice, aeródromo inseguro.", "Regrese a aterrizar."], correctIndex: 1, explanation: "Para una aeronave en vuelo, la luz roja destellante significa 'aeródromo inseguro, no aterrice' (airport unsafe, do not land). 'Ceda el paso y continúe circulando' corresponde a la roja fija.", cite: "PHAK Cap. 14, Fig. 14-42 (light gun signals)" },
  { id: "q_laof_1_044", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es el código respondedor para pérdida de comunicaciones?", options: ["7500.", "7700.", "7600."], correctIndex: 2, explanation: "El código transponder 7600 corresponde a falla o pérdida de comunicaciones. 7500 es interferencia ilícita (secuestro) y 7700 es emergencia general.", cite: "AIM 6-4-2 / PHAK Cap. 14" },
  { id: "q_laof_1_045", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es el código respondedor para emergencias?", options: ["7700.", "7500.", "7600."], correctIndex: 0, explanation: "El código transponder 7700 corresponde a emergencia; el propio PHAK indica operar el transponder en Modo A código 7700 en caso de emergencia. 7500 es interferencia ilícita y 7600 falla de comunicaciones.", cite: "AIM 6-2-4 / PHAK Cap. 14" },
  { id: "q_laof_1_046", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es el código respondedor para interferencia ilícita?", options: ["7500.", "7700.", "7600."], correctIndex: 0, explanation: "El código transponder 7500 corresponde a interferencia ilícita (hijack). 7700 es emergencia y 7600 pérdida de comunicaciones.", cite: "AIM 6-2-4 / PHAK Cap. 14" },
  { id: "q_laof_1_047", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿A qué se refiere el término Aeronautical Decision-Making (ADM)?", options: ["Al conjunto de reglas de diseño de procedimientos en áreas terminales (TMA) que determinan los mínimos de aproximación de no precisión.", "Al conjunto de reglas de diseño de procedimientos en áreas terminales (TMA) que determinan los mínimos de aproximación ILS.", "A una visión sistémica de los procesos mentales de los pilotos para consistentemente determinar los mejores cursos de acción."], correctIndex: 2, explanation: "El PHAK define ADM como un enfoque sistemático de los procesos mentales que usan los pilotos para determinar consistentemente el mejor curso de acción ante un conjunto de circunstancias. Los distractores describen criterios de diseño de procedimientos terminales (TERPS), ajenos al concepto.", cite: "PHAK Cap. 2 (Aeronautical Decision-Making)" },
  { id: "q_laof_1_048", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué actitud peligrosa se caracteriza por un piloto que toma riesgos innecesarios a efecto de impresionar a otros?", options: ["Impresionabilidad.", "Macho.", "Impulsividad."], correctIndex: 1, explanation: "La actitud peligrosa 'macho' ('I can do it') caracteriza al piloto que toma riesgos innecesarios para probarse o impresionar a otros; es una de las cinco actitudes peligrosas del PHAK junto con antiautoridad, impulsividad, invulnerabilidad y resignación. 'Impresionabilidad' no es una de las cinco actitudes y la impulsividad consiste en actuar sin pensar, no en presumir.", cite: "PHAK Cap. 2, Fig. 2-4 (hazardous attitudes)" },
  { id: "q_laof_1_049", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿El acrónimo PAVE divide los riesgos de una operación en qué categorías?", options: ["Pilot-in-command, Aircraft, enVironment, External pressures.", "Pilot-in-command, Airspace, Visibility, Emergencies.", "Pilot-in-command, Attitude, Vulnerability, External pressures."], correctIndex: 0, explanation: "El checklist PAVE divide los riesgos del vuelo en Pilot-in-command, Aircraft, enVironment y External pressures. Las otras combinaciones (Airspace/Visibility/Emergencies o Attitude/Vulnerability) no corresponden al acrónimo del PHAK.", cite: "PHAK Cap. 2 (PAVE checklist)" },
  { id: "q_laof_1_050", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es la principal función de los alerones?", options: ["Controlar el movimiento de guiñada de la aeronave.", "Controlar el movimiento de alabeo de la aeronave.", "Incrementar la sustentación del perfil alar durante el despegue."], correctIndex: 1, explanation: "Los alerones controlan el alabeo (roll) alrededor del eje longitudinal mediante la deflexión diferencial en los extremos del ala. La guiñada la controla el timón de dirección, y aunque cambian la sustentación local, su función no es incrementar la sustentación en el despegue (eso es de los flaps).", cite: "PHAK Cap. 6 (flight controls)" },
  { id: "q_laof_1_051", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "INSTR", text: "¿Qué instrumento mide directamente la presión estática para indicar la altitud?", options: ["El indicador de velocidad vertical.", "El altímetro.", "El indicador de viraje."], correctIndex: 1, explanation: "El altímetro es el instrumento que mide directamente la presión estática y la convierte en indicación de altitud mediante cápsulas aneroides. El VSI usa presión estática pero indica régimen de cambio, no altitud, y el indicador de viraje es giroscópico.", cite: "PHAK Cap. 8 (altímetro)" },
  { id: "q_laof_1_052", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué ocurre con la densidad del aire cuando aumenta la temperatura y la presión permanece constante?", options: ["Aumenta gradualmente hasta la presión de la atmósfera estándar.", "Disminuye.", "Permanece igual."], correctIndex: 1, explanation: "A presión constante, la densidad del aire es inversamente proporcional a la temperatura: al aumentar la temperatura la densidad disminuye. Esta es la base del concepto de altitud de densidad y su efecto adverso en el rendimiento.", cite: "PHAK Cap. 4 (atmósfera)" },
  { id: "q_laof_1_053", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es la principal función de los flaps?", options: ["Mejorar la eficiencia del timón de dirección.", "Reducir el peso efectivo (MTOW) de la aeronave.", "Incrementar la sustentación y el arrastre para facilitar despegues y aterrizajes."], correctIndex: 2, explanation: "Los flaps son dispositivos hipersustentadores que incrementan la sustentación y también el arrastre, permitiendo despegar y aterrizar a menores velocidades y con mayores ángulos de descenso. No actúan sobre el timón de dirección ni reducen el peso de la aeronave.", cite: "PHAK Cap. 6 (flaps)" },
  { id: "q_laof_1_054", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué fenómeno provoca una disminución de la sustentación cuando el ángulo de ataque excede el crítico?", options: ["La pérdida (stall).", "La sustentación inducida.", "La precesión giroscópica."], correctIndex: 0, explanation: "Cuando el ángulo de ataque excede el ángulo crítico, el flujo se desprende del extradós y la sustentación cae bruscamente: eso es la pérdida (stall). La precesión giroscópica es un fenómeno del rotor/hélice y la 'sustentación inducida' no es un fenómeno que reduzca la sustentación.", cite: "PHAK Cap. 5 (stalls)" },
  { id: "q_laof_1_055", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es la finalidad principal del compensador (trim tab)?", options: ["Incrementar la potencia disponible del motor.", "Reducir las fuerzas que el piloto debe ejercer sobre los controles.", "Mejorar el desempeño del motor al incrementar la potencia disponible por efecto termodinámico."], correctIndex: 1, explanation: "El compensador (trim tab) tiene por finalidad eliminar o reducir las fuerzas que el piloto debe mantener sobre los controles para conservar una actitud deseada. No guarda relación alguna con la potencia del motor.", cite: "PHAK Cap. 6 (trim systems)" },
  { id: "q_laof_1_056", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué tipo de hielo representa generalmente el mayor peligro para una aeronave?", options: ["Hielo transparente (clear ice).", "Escarcha (frost).", "Rocío congelado."], correctIndex: 0, explanation: "El hielo transparente (clear ice) es generalmente el más peligroso: se forma con gotas grandes subenfriadas, es pesado, denso, se adhiere firmemente y es difícil de remover, deformando el perfil. La escarcha y el rocío congelado son depósitos superficiales de mucho menor peso, aunque también degradan la sustentación.", cite: "PHAK Cap. 12 (structural icing)" },
  { id: "q_laof_1_057", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "INSTR", text: "¿Qué información proporciona el horizonte artificial?", options: ["La velocidad respecto al suelo.", "El régimen de ascenso/descenso de la aeronave expresado en pies por minuto.", "La actitud de la aeronave respecto al horizonte natural."], correctIndex: 2, explanation: "El horizonte artificial (indicador de actitud) presenta la actitud de la aeronave en cabeceo y alabeo respecto al horizonte natural. La velocidad respecto al suelo la da el GPS/DME y el régimen de ascenso/descenso lo da el VSI.", cite: "PHAK Cap. 8 (attitude indicator)" },
  { id: "q_laof_1_058", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué ocurre normalmente con la distancia de despegue en un aeropuerto de gran altitud y alta temperatura?", options: ["No cambia pues se compensa por la presión atmosférica.", "Disminuye.", "Aumenta."], correctIndex: 2, explanation: "A gran altitud y alta temperatura la altitud de densidad es elevada: el aire menos denso reduce el empuje, la sustentación y la eficiencia de la hélice, por lo que la distancia de despegue aumenta. No existe compensación automática por presión atmosférica.", cite: "PHAK Cap. 11 (performance)" },
  { id: "q_laof_1_059", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué elemento produce principalmente la sustentación en un ala?", options: ["La diferencia de presión generada por el perfil alar y el ángulo de ataque.", "La potencia que entrega el motor y el flujo de aire que desplaza.", "La velocidad de tierra (ground speed)."], correctIndex: 0, explanation: "La sustentación se produce principalmente por la diferencia de presiones que genera el perfil alar en función del ángulo de ataque (Bernoulli/Newton). La potencia del motor produce empuje, no sustentación directa, y la velocidad de tierra es irrelevante aerodinámicamente.", cite: "PHAK Cap. 5 (lift)" },
  { id: "q_laof_1_060", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es la principal causa de un spin?", options: ["Un reducido ajuste de potencia del motor.", "La no-coordinación del ajuste potencia/paso en aeronaves de paso variable.", "Una pérdida asimétrica combinada con guiñada."], correctIndex: 2, explanation: "Un spin (barrena) resulta de una pérdida agravada asimétrica: un ala más 'perdida' que la otra combinada con guiñada, que produce la autorrotación. La potencia o el paso de la hélice no son la causa del fenómeno.", cite: "PHAK Cap. 5 (spins)" },
  { id: "q_laof_1_061", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "INSTR", text: "¿Cuál es el propósito del tubo pitot?", options: ["Medir la presión dinámica para calcular la velocidad indicada.", "Medir la presión estática para calcular la velocidad respecto a la tierra (ground speed).", "Determinar la dirección del viento en vuelo."], correctIndex: 0, explanation: "El tubo pitot capta la presión de impacto (dinámica más estática); el sistema la compara con la estática para obtener la presión dinámica con la que se calcula la velocidad indicada. No mide velocidad respecto al suelo ni dirección del viento.", cite: "PHAK Cap. 8 (sistema pitot-estático)" },
  { id: "q_laof_1_062", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "INSTR", text: "¿Qué sucede con la velocidad verdadera (true airspeed) al aumentar la altitud, manteniendo constante la velocidad indicada?", options: ["Permanece exactamente igual.", "Disminuye.", "Aumenta."], correctIndex: 2, explanation: "Manteniendo la velocidad indicada constante, la velocidad verdadera aumenta con la altitud (aproximadamente 2% por cada 1,000 ft) porque la menor densidad hace que la misma presión dinámica corresponda a mayor velocidad real. Por eso TAS > IAS en altura.", cite: "PHAK Cap. 8 (tipos de velocidad)" },
  { id: "q_laof_1_063", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué condición favorece la formación de niebla por radiación?", options: ["Cielos despejados, poco viento y alta humedad durante la noche.", "Temperaturas elevadas durante la tarde sobre cuerpos de agua.", "Vientos fuertes y aire frío y húmedo sin importar condiciones de temperatura del terreno."], correctIndex: 0, explanation: "La niebla de radiación se forma en noches de cielo despejado, viento calmo o débil y alta humedad relativa: el suelo se enfría por radiación y enfría el aire adyacente hasta su punto de rocío. Vientos fuertes o superficies de agua favorecen otros tipos de niebla (advección), no la de radiación.", cite: "PHAK Cap. 12 (fog)" },
  { id: "q_laof_1_064", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Qué combustible debe utilizarse únicamente si está aprobado para la aeronave y el motor?", options: ["Para aeronaves de pistón, el combustible con mayor concentración de color disponible.", "Cualquier combustible automotriz de alto octanaje con aditivos aeronáuticos certificados.", "El especificado por el fabricante en el Manual de Vuelo o POH."], correctIndex: 2, explanation: "Solo debe utilizarse el combustible del grado especificado por el fabricante en el Manual de Vuelo/POH (o uno aprobado como alternativo). El color no indica 'calidad' y el combustible automotriz solo es admisible con un STC específico, no de forma genérica.", cite: "PHAK Cap. 7 (fuel systems)" },
  { id: "q_laof_1_065", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué efecto tiene desplazar el centro de gravedad demasiado hacia atrás?", options: ["Incrementa significativamente la estabilidad longitudinal.", "Elimina la tendencia a la pérdida (stall).", "Reduce la estabilidad longitudinal y puede dificultar la recuperación de una pérdida."], correctIndex: 2, explanation: "Un centro de gravedad demasiado atrasado reduce la estabilidad longitudinal y hace a la aeronave menos capaz de recuperarse de una pérdida o barrena, pudiendo volverla peligrosamente inestable en cabeceo. Lejos de eliminar la pérdida, agrava sus consecuencias.", cite: "PHAK Cap. 10 (weight and balance)" },
  { id: "q_laof_1_066", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el propósito principal de un NOTAM?", options: ["Informar cambios o condiciones temporales relevantes para la operación aérea.", "Reportar pronósticos meteorológicos de una estación con periodicidad definida.", "Publicar únicamente horarios de aeropuertos y disponibilidad de servicios de emergencia."], correctIndex: 0, explanation: "El NOTAM difunde información esencial de carácter temporal o de corto plazo relevante para la operación (cierres de pista, ayudas fuera de servicio, obstáculos, etc.). No es un producto de pronóstico meteorológico ni se limita a horarios de aeropuertos.", cite: "PHAK Cap. 1 / AIM 5-1-3 (NOTAM)" },
  { id: "q_laof_1_067", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "INSTR", text: "¿Qué indica una lectura positiva en el indicador de velocidad vertical (VSI)?", options: ["Que la aeronave está ascendiendo.", "Que la aeronave está acelerando horizontalmente.", "Que la aeronave está aumentando su velocidad indicada."], correctIndex: 0, explanation: "Una lectura positiva del VSI indica que la presión estática está disminuyendo, es decir, que la aeronave asciende a razón de los pies por minuto indicados. El instrumento no mide aceleración ni velocidad indicada.", cite: "PHAK Cap. 8 (VSI)" },
  { id: "q_laof_1_068", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es la función principal del aceite del motor?", options: ["Lubricar, ayudar a enfriar y limpiar los componentes internos del motor.", "Incrementar directamente la potencia del motor por efecto termodinámico.", "Controlar la mezcla aire-combustible al modular su densidad/viscosidad."], correctIndex: 0, explanation: "El aceite del motor lubrica las partes móviles, ayuda a enfriar el motor, limpia y arrastra contaminantes, además de sellar y proteger contra corrosión. No incrementa la potencia ni regula la mezcla.", cite: "PHAK Cap. 7 (oil systems)" },
  { id: "q_laof_1_069", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué representa la velocidad de maniobra (VA)?", options: ["La velocidad mínima de control direccional en tierra (término equivalente a VMCground).", "La velocidad máxima a la que pueden aplicarse movimientos completos y bruscos de los controles sin exceder los límites estructurales bajo las condiciones especificadas.", "La velocidad máxima de estructura (airframe)."], correctIndex: 1, explanation: "VA (velocidad de maniobra) es la velocidad máxima a la que puede aplicarse deflexión completa y abrupta de un control sin exceder los límites estructurales, válida para el peso y condiciones especificados. No es la velocidad máxima estructural (VNE) ni una velocidad de control en tierra.", cite: "PHAK Cap. 5 / glosario (maneuvering speed)" },
  { id: "q_laof_1_070", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "INSTR", text: "¿Qué instrumento depende únicamente del sistema giroscópico y no del sistema pitot-estático?", options: ["Indicador de velocidad terrestre (si el mismo es alimentado por GPS).", "Altímetro.", "Indicador de actitud."], correctIndex: 2, explanation: "El indicador de actitud es un instrumento puramente giroscópico (accionado por vacío o eléctrico) y no recibe presiones del sistema pitot-estático. El altímetro es precisamente un instrumento de presión estática, y un indicador alimentado por GPS no es giroscópico.", cite: "PHAK Cap. 8 (gyroscopic instruments)" },
  { id: "q_laof_1_071", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué sucede con la presión atmosférica conforme aumenta la altitud?", options: ["Aumenta.", "Permanece constante hasta la tropopausa.", "Disminuye."], correctIndex: 2, explanation: "La presión atmosférica disminuye conforme aumenta la altitud, aproximadamente 1 inHg por cada 1,000 ft en niveles bajos. No permanece constante en ningún estrato de la atmósfera.", cite: "PHAK Cap. 4/12 (atmósfera)" },
  { id: "q_laof_1_072", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué efecto tiene un viento de frente durante el despegue?", options: ["Incrementa la distancia de despegue por la resistencia del viento.", "No afecta el rendimiento en condiciones ISA.", "Reduce la distancia necesaria para despegar."], correctIndex: 2, explanation: "Un viento de frente reduce la distancia de despegue: la aeronave alcanza la velocidad aerodinámica de sustentación con menor velocidad respecto al suelo. El viento de frente nunca 'agrega resistencia' que alargue la carrera; eso es un concepto erróneo.", cite: "PHAK Cap. 11 (performance)" },
  { id: "q_laof_1_073", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué control primario produce el movimiento de guiñada?", options: ["Elevador.", "Timón de dirección.", "Alerones."], correctIndex: 1, explanation: "El timón de dirección (rudder) es el control primario que produce la guiñada (yaw) alrededor del eje vertical. El elevador controla el cabeceo y los alerones el alabeo.", cite: "PHAK Cap. 6 (flight controls)" },
  { id: "q_laof_1_074", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué representa el centro de presión de un ala?", options: ["El punto donde actúa la fuerza aerodinámica resultante.", "El punto donde se ubica el centro de gravedad.", "El punto que el fabricante determina como “datum” para centrar el eje de potencia del motor."], correctIndex: 0, explanation: "El centro de presión es el punto sobre la cuerda donde se considera que actúa la fuerza aerodinámica resultante del ala. No coincide conceptualmente con el centro de gravedad ni con el datum de peso y balance.", cite: "PHAK Cap. 5 (center of pressure)" },
  { id: "q_laof_1_075", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué condición favorece la formación de turbulencia mecánica?", options: ["Cielos despejados y viento fuerte sobre superficies planas, como lagos y mares.", "Viento fuerte sobre obstáculos como montañas o edificios.", "Temperaturas uniformes en toda la atmósfera."], correctIndex: 1, explanation: "La turbulencia mecánica se genera cuando el viento fuerte fluye sobre obstáculos como edificios, hangares, terreno irregular o montañas, creando remolinos a sotavento. Superficies planas de agua o atmósferas térmicamente uniformes no producen este tipo de turbulencia.", cite: "PHAK Cap. 12 (turbulencia mecánica)" },
  { id: "q_laof_1_076", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el propósito principal de una inspección previa al vuelo?", options: ["Verificar que la aeronave sea segura para operar.", "Comprobar el funcionamiento de los radios para operaciones IFR en espacio aéreo no-controlado.", "Confirmar únicamente el nivel y calidad del combustible."], correctIndex: 0, explanation: "El propósito de la inspección previa al vuelo es determinar que la aeronave está aeronavegable y es segura para operar, revisando estructura, mandos, fluidos y equipo requerido. Verificar radios o combustible son solo elementos parciales de esa verificación integral.", cite: "AFH Cap. 2 / PHAK (preflight)" },
  { id: "q_laof_1_077", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué ocurre cuando aumenta el factor de carga en un viraje?", options: ["La velocidad de pérdida aumenta.", "La velocidad de pérdida disminuye.", "La velocidad de pérdida permanece constante."], correctIndex: 0, explanation: "La velocidad de pérdida aumenta con la raíz cuadrada del factor de carga: en un viraje nivelado de 60° (2 g) crece cerca de 40%. Por eso los virajes cerrados a baja velocidad son críticos.", cite: "PHAK Cap. 5 (load factor y stall speed)" },
  { id: "q_laof_1_078", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es el objetivo principal de equilibrar correctamente la mezcla aire-combustible?", options: ["Obtener un funcionamiento eficiente del motor.", "Reducir la sustentación.", "Incrementar el peso útil de operación."], correctIndex: 0, explanation: "El ajuste correcto de la mezcla aire-combustible busca la proporción adecuada para cada altitud y régimen, logrando un funcionamiento eficiente del motor (potencia, consumo y temperaturas correctas). La mezcla no afecta la sustentación ni el peso útil.", cite: "PHAK Cap. 7 (mixture)" },
  { id: "q_laof_1_079", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué fenómeno meteorológico suele asociarse con nubes cumulonimbus?", options: ["Niebla por radiación.", "Tormentas eléctricas.", "Llovizna ligera estable y niebla de advección (advection fog)."], correctIndex: 1, explanation: "Las nubes cumulonimbus son las nubes de tormenta: se asocian a tormentas eléctricas, turbulencia severa, granizo, cortante de viento y microrráfagas. La niebla de radiación y la llovizna estable corresponden a masas de aire estables, lo opuesto a un CB.", cite: "PHAK Cap. 12 (thunderstorms)" },
  { id: "q_laof_1_080", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Qué sucede normalmente con el rendimiento del motor de pistón conforme aumenta la altitud?", options: ["Aumenta por la menor resistencia aerodinámica.", "Disminuye debido a la menor densidad del aire.", "Permanece constante."], correctIndex: 1, explanation: "El rendimiento del motor de pistón normalmente aspirado disminuye con la altitud porque la menor densidad del aire reduce la masa de oxígeno disponible para la combustión. La menor resistencia aerodinámica no compensa la pérdida de potencia del motor.", cite: "PHAK Cap. 7/11 (motor y performance)" },
  { id: "q_laof_1_081", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es la función principal del estabilizador horizontal?", options: ["Proporcionar estabilidad longitudinal.", "Generar la mayor parte de la sustentación en el empenaje de la aeronave.", "Compensar el efecto del viento cruzado."], correctIndex: 0, explanation: "El estabilizador horizontal proporciona estabilidad longitudinal (en cabeceo), generando normalmente una carga aerodinámica hacia abajo que equilibra el momento del ala/CG. No genera la sustentación principal ni compensa viento cruzado.", cite: "PHAK Cap. 5/6 (empenaje y estabilidad)" },
  { id: "q_laof_1_082", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué significa que una aeronave sea longitudinalmente estable?", options: ["Que la misma tiende a regresar a su actitud de cabeceo después de una perturbación.", "Que la misma mantiene automáticamente el rumbo.", "Que corrige el efecto de rol holandés (dutch roll)."], correctIndex: 0, explanation: "Una aeronave longitudinalmente estable tiende a regresar por sí sola a su actitud de cabeceo compensada después de una perturbación. Mantener el rumbo es estabilidad direccional y el dutch roll se relaciona con la estabilidad lateral-direccional.", cite: "PHAK Cap. 5 (estabilidad longitudinal)" },
  { id: "q_laof_1_083", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué información proporciona un METAR?", options: ["El pronóstico meteorológico de un área de control expandida (FIR/UIR).", "El pronóstico meteorológico a esperarse en un aeródromo.", "Las condiciones meteorológicas observadas en un aeródromo."], correctIndex: 2, explanation: "El METAR es el reporte de las condiciones meteorológicas observadas en un aeródromo a una hora determinada. El pronóstico de aeródromo es el TAF, y los pronósticos de área cubren regiones, no son el METAR.", cite: "PHAK Cap. 13 (METAR)" },
  { id: "q_laof_1_084", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué tipo de resistencia aerodinámica aumenta conforme se incrementa la velocidad?", options: ["Resistencia generativa.", "Resistencia parásita.", "Resistencia inducida."], correctIndex: 1, explanation: "La resistencia parásita aumenta con el cuadrado de la velocidad; la resistencia inducida, por el contrario, disminuye al aumentar la velocidad. 'Resistencia generativa' no existe como término aerodinámico.", cite: "PHAK Cap. 5 (drag)" },
  { id: "q_laof_1_085", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Qué sistema evita que el combustible deje de fluir cuando la aeronave cambia de actitud?", options: ["El compensador del elevador.", "Sistema de ventilación y alimentación diseñado para mantener el flujo.", "El sistema pitot-estático (cuando instalado)"], correctIndex: 1, explanation: "El sistema de alimentación y ventilación del combustible (venteos, bombas, acumuladores y diseño de tanques) está concebido para mantener el flujo hacia el motor en los cambios de actitud de la aeronave. El compensador y el sistema pitot-estático no guardan relación con el flujo de combustible.", cite: "PHAK Cap. 7 (fuel systems)" },
  { id: "q_laof_1_086", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "INSTR", text: "¿Qué representa la línea del horizonte en el indicador de actitud?", options: ["La referencia entre la aeronave y el horizonte terrestre.", "La trayectoria de vuelo deseada.", "La dirección del viento."], correctIndex: 0, explanation: "La línea del horizonte del indicador de actitud representa el horizonte terrestre y sirve de referencia entre éste y el avión miniatura para leer cabeceo y alabeo. No representa la trayectoria deseada ni la dirección del viento.", cite: "PHAK Cap. 8 (attitude indicator)" },
  { id: "q_laof_1_087", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el principal beneficio de utilizar listas de verificación (checklists)?", options: ["Consultar los ajustes recomendados por el fabricante para mezcla de combustible.", "Reducir la posibilidad de omitir procedimientos importantes.", "Asegurar la redundancia de funciones en cabinas de dos o más tripulantes."], correctIndex: 1, explanation: "El principal beneficio de las listas de verificación es reducir la posibilidad de omitir pasos o procedimientos importantes, garantizando configuraciones correctas de manera sistemática. No son un catálogo de ajustes de mezcla ni dependen de tener dos tripulantes.", cite: "PHAK Cap. 2 / AFH Cap. 1 (checklists)" },
  { id: "q_laof_1_088", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué condición favorece la aparición de hipoxia en un piloto?", options: ["Utilizar el sistema de oxígeno de la aeronave y/o mascarillas suplementarias de oxígeno.", "Volar a gran altitud sin oxígeno suplementario cuando es requerido.", "Permitir la operación correcta del sistema de presurización de una aeronave."], correctIndex: 1, explanation: "La hipoxia hipóxica aparece al volar a gran altitud sin oxígeno suplementario cuando éste es requerido: la menor presión parcial de oxígeno impide su transferencia adecuada a la sangre. Usar el oxígeno de a bordo o una presurización correcta son precisamente las defensas contra la hipoxia.", cite: "PHAK Cap. 17 (hipoxia)" },
  { id: "q_laof_1_089", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es el propósito principal del sistema eléctrico de una aeronave ligera?", options: ["Alimentar los equipos eléctricos y recargar la batería durante el funcionamiento del motor.", "Proporcionar empuje adicional al motor a través del sistema turbo-cargador.", "Controlar el movimiento de las superficies de vuelo (en aeronaves de control hidráulico)."], correctIndex: 0, explanation: "El sistema eléctrico de una aeronave ligera alimenta los equipos eléctricos y de aviónica y recarga la batería mientras el motor acciona el alternador. No produce empuje ni mueve las superficies de vuelo en aeronaves de mando mecánico.", cite: "PHAK Cap. 7 (electrical system)" },
  { id: "q_laof_1_090", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el propósito principal del timón de profundidad?", options: ["Controlar el movimiento de guiñada de la aeronave.", "Controlar el movimiento de cabeceo de la aeronave.", "Incrementar la sustentación durante el aterrizaje."], correctIndex: 1, explanation: "El timón de profundidad (elevador) controla el cabeceo alrededor del eje transversal, variando la carga aerodinámica del empenaje. La guiñada es del timón de dirección y la sustentación adicional en aterrizaje corresponde a los flaps.", cite: "PHAK Cap. 6 (elevator)" },
  { id: "q_laof_1_091", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué sucede con la velocidad de pérdida (stall) cuando una aeronave acumula hielo sobre el ala?", options: ["Permanece igual siempre que la potencia del motor no cambie.", "Disminuye por el incremento de la sustentación.", "Aumenta debido a la alteración del perfil aerodinámico."], correctIndex: 2, explanation: "El hielo sobre el ala altera el perfil aerodinámico, reduce el coeficiente máximo de sustentación y aumenta el peso, por lo que la velocidad de pérdida aumenta. Jamás disminuye: el hielo degrada, no incrementa, la sustentación.", cite: "PHAK Cap. 5/12 (icing y stall)" },
  { id: "q_laof_1_092", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es la principal función del timón de dirección compensable (rudder trim), cuando está instalado?", options: ["Incrementar la autoridad del timón de dirección durante el despegue.", "Compensar automáticamente los efectos de la turbulencia severa.", "Reducir la fuerza que el piloto debe aplicar sobre los pedales para mantener el vuelo coordinado."], correctIndex: 2, explanation: "El rudder trim reduce la fuerza sostenida que el piloto debe aplicar sobre los pedales para mantener el vuelo coordinado (por ejemplo, contrarrestando efectos de potencia/torque). No aumenta la autoridad del control ni actúa automáticamente contra turbulencia.", cite: "PHAK Cap. 6 (trim systems)" },
  { id: "q_laof_1_093", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el recíproco del rumbo 144º?", options: ["324º.", "344º.", "314º."], correctIndex: 0, explanation: "El recíproco se obtiene sumando o restando 180°: 144° + 180° = 324°. Las opciones 344° y 314° resultan de sumar 200° o 170°, no 180°.", cite: "Cálculo de rumbo recíproco (±180°)" },
  { id: "q_laof_1_094", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el recíproco del rumbo 324º?", options: ["124º.", "144º.", "164º."], correctIndex: 1, explanation: "El recíproco de 324° es 324° − 180° = 144°. Las opciones 124° y 164° no distan 180° del rumbo dado.", cite: "Cálculo de rumbo recíproco (±180°)" },
  { id: "q_laof_1_095", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el recíproco del rumbo 082º?", options: ["222º.", "242º.", "262º."], correctIndex: 2, explanation: "El recíproco de 082° es 082° + 180° = 262°. Las opciones 222° y 242° no distan 180° del rumbo dado.", cite: "Cálculo de rumbo recíproco (±180°)" },
  { id: "q_laof_1_096", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el recíproco del rumbo 262º?", options: ["062º.", "082º.", "042º."], correctIndex: 1, explanation: "El recíproco de 262° es 262° − 180° = 082°. Las opciones 062° y 042° no distan 180° del rumbo dado.", cite: "Cálculo de rumbo recíproco (±180°)" },
  { id: "q_laof_1_097", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el recíproco del rumbo 037º?", options: ["247º.", "207º.", "217º."], correctIndex: 2, explanation: "El recíproco de 037° es 037° + 180° = 217°. Las opciones 247° y 207° no distan 180° del rumbo dado.", cite: "Cálculo de rumbo recíproco (±180°)" },
  { id: "q_laof_1_098", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué efecto produce el efecto suelo durante el despegue y aterrizaje?", options: ["Incrementa el arrastre parásito debido a la proximidad con el terreno.", "Reduce la resistencia inducida y mejora temporalmente el desempeño del ala.", "Disminuye la sustentación al alterar el flujo de aire sobre el ala."], correctIndex: 1, explanation: "En efecto suelo, la proximidad al terreno interfiere con los vórtices de punta de ala y reduce la resistencia inducida, mejorando temporalmente el desempeño del ala (el avión 'flota'). No incrementa el arrastre parásito ni disminuye la sustentación.", cite: "PHAK Cap. 5 (ground effect)" },
  { id: "q_laof_1_099", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué sucede normalmente cuando se incrementa el ángulo de banqueo manteniendo la altitud?", options: ["Disminuye la velocidad de pérdida.", "Disminuye el peso de la aeronave.", "Aumenta el factor de carga."], correctIndex: 2, explanation: "Al aumentar el ángulo de banqueo manteniendo la altitud, la sustentación debe incrementarse para sostener el peso, elevando el factor de carga (2 g a 60° de banqueo). El peso no cambia y la velocidad de pérdida aumenta, no disminuye.", cite: "PHAK Cap. 5 (load factor en virajes)" },
  { id: "q_laof_1_100", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es la función principal del estabilizador vertical?", options: ["Generar sustentación durante el ascenso.", "Reducir el factor de carga en los virajes.", "Proporcionar estabilidad direccional."], correctIndex: 2, explanation: "El estabilizador vertical proporciona estabilidad direccional (en guiñada), actuando como veleta que mantiene la nariz al viento relativo. No genera sustentación de ascenso ni reduce el factor de carga.", cite: "PHAK Cap. 5/6 (estabilidad direccional)" },
  { id: "q_laof_1_101", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es el propósito principal del sistema de ventilación del tanque de combustible?", options: ["Enfriar el combustible durante el crucero.", "Incrementar la presión del combustible antes de llegar al motor.", "Permitir el ingreso de aire para evitar la formación de vacío conforme se consume el combustible."], correctIndex: 2, explanation: "El venteo del tanque de combustible permite la entrada de aire para igualar presiones y evitar que se forme vacío conforme se consume el combustible, lo que interrumpiría el flujo o dañaría el tanque. No enfría ni presuriza el combustible.", cite: "PHAK Cap. 7 (fuel tank vents)" },
  { id: "q_laof_1_102", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué ocurre cuando el centro de gravedad se encuentra demasiado adelantado?", options: ["Disminuye considerablemente la estabilidad longitudinal.", "Se incrementa la estabilidad longitudinal, pero puede dificultarse la rotación y el flare.", "Se elimina prácticamente el riesgo de pérdida."], correctIndex: 1, explanation: "Con el centro de gravedad muy adelantado la aeronave se vuelve más estable longitudinalmente (nariz pesada), pero pueden dificultarse la rotación en el despegue y el flare en el aterrizaje, además de aumentar la velocidad de pérdida. La estabilidad no disminuye ni desaparece el riesgo de pérdida.", cite: "PHAK Cap. 10 (efectos del CG)" },
  { id: "q_laof_1_103", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es la principal ventaja de un ala con relación de aspecto elevada (high aspect ratio)?", options: ["Produce menor resistencia inducida.", "Permite alcanzar mayores velocidades de pérdida.", "Incrementa significativamente la resistencia parásita."], correctIndex: 0, explanation: "Un ala de alta relación de aspecto (alargamiento) produce menor resistencia inducida para una misma sustentación, al reducir la intensidad de los vórtices de punta; por eso la usan planeadores y aviones de gran autonomía. No eleva la velocidad de pérdida ni busca aumentar la resistencia parásita.", cite: "PHAK Cap. 5 (aspect ratio e induced drag)" },
  { id: "q_laof_1_104", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Qué condición favorece la aparición de engelamiento del carburador?", options: ["Temperaturas inferiores a –20 °C con aire muy seco.", "Únicamente lluvia congelante.", "Aire húmedo con temperaturas moderadas, incluso por encima del punto de congelación."], correctIndex: 2, explanation: "El engelamiento del carburador se produce con aire húmedo y temperaturas moderadas, incluso muy por encima del punto de congelación (típicamente hasta 21 °C / 70 °F), por el enfriamiento por expansión y vaporización en el venturi. No requiere lluvia congelante ni temperaturas muy bajas; con aire muy seco no ocurre.", cite: "PHAK Cap. 7 (carburetor icing)" },
  { id: "q_laof_1_105", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es la finalidad principal de las descargas de estática instaladas en algunas aeronaves?", options: ["Disipar la electricidad estática acumulada durante el vuelo.", "Incrementar el alcance de las comunicaciones VHF.", "Reducir la resistencia inducida del ala."], correctIndex: 0, explanation: "Las descargas de estática (static wicks/dischargers) disipan hacia la atmósfera la electricidad estática acumulada por fricción en vuelo, evitando interferencias de radio (precipitación estática). Su ausencia degrada las comunicaciones, pero su función no es aumentar el alcance VHF ni reducir resistencia.", cite: "PHAK Cap. 7 (static dischargers)" },
  { id: "q_laof_1_106", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué ocurre normalmente con la presión dinámica cuando aumenta la velocidad de la aeronave?", options: ["Aumenta.", "Permanece constante.", "Disminuye."], correctIndex: 0, explanation: "La presión dinámica es q = ½ρV²: aumenta con el cuadrado de la velocidad de la aeronave. Es la base de la indicación de velocidad del anemómetro.", cite: "PHAK Cap. 4/5 (presión dinámica)" },
  { id: "q_laof_1_107", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es el propósito principal del sistema alternativo de aire del motor (alternate air)?", options: ["Permitir el suministro de aire al motor cuando la toma principal se encuentra obstruida.", "Enfriar el motor durante el ascenso.", "Incrementar la potencia disponible durante el despegue."], correctIndex: 0, explanation: "El sistema de aire alternativo (alternate air / calefacción de carburador) permite suministrar aire al motor desde una fuente alterna cuando la toma principal está obstruida, por ejemplo por hielo de impacto o del carburador. No es un sistema de enfriamiento ni de aumento de potencia; de hecho suele reducirla ligeramente.", cite: "PHAK Cap. 7 (alternate air / carb heat)" },
  { id: "q_laof_1_108", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué condición puede provocar hiperventilación en un piloto?", options: ["Respirar aire con baja concentración de oxígeno.", "Respirar aire excesivamente húmedo.", "Respirar de manera excesivamente rápida y profunda debido al estrés o la ansiedad."], correctIndex: 2, explanation: "La hiperventilación se produce al respirar de manera excesivamente rápida y profunda, típicamente por estrés, miedo o ansiedad, eliminando demasiado CO2 de la sangre. Respirar aire pobre en oxígeno produce hipoxia, un problema distinto aunque con síntomas similares.", cite: "PHAK Cap. 17 (hiperventilación)" },
  { id: "q_laof_1_109", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es un síntoma común de intoxicación por monóxido de carbono?", options: ["Incremento de la agudeza visual.", "Aumento de la coordinación motora.", "Dolor de cabeza y somnolencia."], correctIndex: 2, explanation: "La intoxicación por monóxido de carbono produce dolor de cabeza, somnolencia, mareo y deterioro del juicio, porque el CO desplaza al oxígeno en la hemoglobina. Nunca mejora la visión ni la coordinación; las degrada.", cite: "PHAK Cap. 17 (monóxido de carbono)" },
  { id: "q_laof_1_110", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué es la desorientación espacial?", options: ["La incapacidad para determinar la posición mediante navegación visual.", "La incapacidad del piloto para determinar correctamente la actitud o movimiento de la aeronave.", "La pérdida temporal de comunicaciones con el ATC."], correctIndex: 1, explanation: "La desorientación espacial es la incapacidad del piloto para determinar correctamente la actitud, altitud o movimiento de la aeronave respecto a la superficie, por conflicto entre los sentidos vestibular, visual y propioceptivo. No se refiere a la navegación visual ni a las comunicaciones.", cite: "PHAK Cap. 17 (spatial disorientation)" },
  { id: "q_laof_1_111", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué es una ilusión de horizonte falso?", options: ["Una falla del horizonte artificial.", "La percepción errónea del horizonte causada por referencias visuales engañosas.", "La desaparición del horizonte debido exclusivamente a niebla."], correctIndex: 1, explanation: "La ilusión de horizonte falso es la percepción errónea del horizonte causada por referencias visuales engañosas: capas de nubes inclinadas, luces en tierra confundidas con estrellas, terreno oscuro. No es una falla del instrumento ni requiere niebla.", cite: "PHAK Cap. 17 (false horizon)" },
  { id: "q_laof_1_112", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es la función principal del diedro en el ala?", options: ["Reducir la resistencia parásita.", "Incrementar la estabilidad lateral de la aeronave.", "Incrementar la velocidad de pérdida."], correctIndex: 1, explanation: "El diedro (ángulo de las alas hacia arriba respecto a la horizontal) incrementa la estabilidad lateral: ante un desplazamiento lateral, el ala baja aumenta su ángulo de ataque efectivo y tiende a nivelar el avión. No reduce la resistencia parásita ni incrementa la velocidad de pérdida.", cite: "PHAK Cap. 5 (dihedral y estabilidad lateral)" },
  { id: "q_laof_1_113", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué es el adverse yaw?", options: ["La tendencia del avión a ascender durante un viraje.", "La pérdida de efectividad del timón de dirección.", "La tendencia de la nariz a desplazarse en sentido contrario al viraje iniciado por los alerones."], correctIndex: 2, explanation: "El adverse yaw es la tendencia de la nariz a guiñar en sentido contrario al viraje: el alerón que baja genera más sustentación y más resistencia inducida en el ala que sube. Se contrarresta con timón de dirección coordinado.", cite: "PHAK Cap. 5/6 (adverse yaw)" },
  { id: "q_laof_1_114", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué caracteriza a una aeronave con buena estabilidad estática?", options: ["Nunca requiere correcciones del piloto.", "Tiende inicialmente a regresar a su condición de equilibrio después de una perturbación.", "Elimina completamente las oscilaciones en vuelo."], correctIndex: 1, explanation: "La estabilidad estática positiva es la tendencia inicial de la aeronave a regresar a su condición de equilibrio tras una perturbación. No significa que nunca requiera correcciones ni que se eliminen las oscilaciones; eso depende de la estabilidad dinámica.", cite: "PHAK Cap. 5 (static stability)" },
  { id: "q_laof_1_115", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué caracteriza a una aeronave con buena estabilidad dinámica?", options: ["La aeronave nunca oscila después de una perturbación.", "Las oscilaciones aumentan continuamente.", "Las oscilaciones disminuyen progresivamente con el tiempo."], correctIndex: 2, explanation: "La estabilidad dinámica positiva se caracteriza porque las oscilaciones posteriores a una perturbación disminuyen progresivamente en amplitud con el tiempo hasta amortiguarse. Si aumentan, la estabilidad dinámica es negativa.", cite: "PHAK Cap. 5 (dynamic stability)" },
  { id: "q_laof_1_116", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Dónde suele encontrarse la turbulencia de estela más intensa?", options: ["Directamente sobre la aeronave.", "Delante de la aeronave.", "Debajo y detrás de la aeronave que la genera."], correctIndex: 2, explanation: "Los vórtices de punta de ala descienden por debajo de la trayectoria de la aeronave que los genera y quedan detrás de ella, por lo que la turbulencia de estela más intensa se encuentra debajo y detrás. Por eso se despega antes del punto de rotación del precedente y se aterriza más allá de su punto de toque.", cite: "PHAK Cap. 5 / AIM 7-4 (wake turbulence)" },
  { id: "q_laof_1_117", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué condición incrementa la intensidad de la turbulencia de estela?", options: ["Baja masa y alta velocidad.", "Temperaturas elevadas únicamente.", "Alta masa y baja velocidad de la aeronave generadora."], correctIndex: 2, explanation: "La intensidad de los vórtices es máxima cuando la aeronave generadora está pesada, en configuración limpia y a baja velocidad ('heavy, clean and slow'), porque el ángulo de ataque y la carga alar son mayores. Baja masa y alta velocidad generan la estela más débil.", cite: "PHAK Cap. 5 / AIM 7-4 (wake turbulence)" },
  { id: "q_laof_1_118", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "INSTR", text: "¿Cuál es la función principal del sistema de vacío en aeronaves convencionales?", options: ["Accionar ciertos instrumentos giroscópicos.", "Enfriar el compartimiento del motor.", "Incrementar la presión del sistema pitot."], correctIndex: 0, explanation: "El sistema de vacío acciona ciertos instrumentos giroscópicos (típicamente el indicador de actitud y el direccional) haciendo girar sus rotores mediante flujo de aire. No enfría el motor ni presuriza el sistema pitot.", cite: "PHAK Cap. 8 (vacuum system)" },
  { id: "q_laof_1_119", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es la función principal del alternador?", options: ["Generar presión hidráulica.", "Regular la mezcla aire-combustible.", "Suministrar energía eléctrica y recargar la batería durante el funcionamiento del motor."], correctIndex: 2, explanation: "El alternador suministra la energía eléctrica de la aeronave en operación y recarga la batería mientras el motor funciona. No genera presión hidráulica ni regula la mezcla.", cite: "PHAK Cap. 7 (electrical system)" },
  { id: "q_laof_1_120", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es la función principal de la batería?", options: ["Proporcionar energía eléctrica cuando el alternador no la suministra.", "Incrementar la potencia del motor durante el despegue.", "Controlar la presión del sistema de combustible."], correctIndex: 0, explanation: "La batería proporciona energía eléctrica cuando el alternador no la suministra: para el arranque y como reserva en caso de falla del alternador. No incrementa la potencia del motor ni controla el combustible.", cite: "PHAK Cap. 7 (electrical system)" },
  { id: "q_laof_1_121", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es la función principal de un magneto?", options: ["Mantener constante el voltaje del alternador.", "Regular la velocidad de la hélice.", "Producir la energía necesaria para las bujías independientemente del sistema eléctrico."], correctIndex: 2, explanation: "Los magnetos son generadores autónomos accionados por el motor que producen la energía de alta tensión para las bujías de forma independiente del sistema eléctrico de la aeronave; por eso el motor sigue funcionando aunque falle el alternador o la batería. No regulan la hélice ni el voltaje del alternador.", cite: "PHAK Cap. 7 (ignition system)" },
  { id: "q_laof_1_122", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es la principal ventaja de una hélice de velocidad constante?", options: ["Eliminar la necesidad de mezcla.", "Mantener el régimen de RPM seleccionado en diferentes condiciones de vuelo.", "Reducir el consumo eléctrico del motor."], correctIndex: 1, explanation: "La hélice de velocidad constante permite mantener el régimen de RPM seleccionado en distintas condiciones de vuelo, ajustando el paso de las palas para aprovechar eficientemente la potencia. No elimina el control de mezcla ni tiene relación con el consumo eléctrico.", cite: "PHAK Cap. 7 (constant-speed propeller)" },
  { id: "q_laof_1_123", fuente: LA_OFICIAL_FUENTE, materia: "aeronaves-motores", tema: "SIST", text: "¿Cuál es la función principal del gobernador de una hélice de velocidad constante?", options: ["Controlar la mezcla aire-combustible.", "Regular la temperatura del aceite.", "Regular automáticamente el ángulo de las palas para mantener las RPM seleccionadas."], correctIndex: 2, explanation: "El gobernador regula automáticamente el ángulo (paso) de las palas mediante presión de aceite para mantener las RPM seleccionadas por el piloto, ante cambios de velocidad o actitud. No controla la mezcla ni la temperatura del aceite.", cite: "PHAK Cap. 7 (propeller governor)" },
  { id: "q_laof_1_124", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué representa el datum en peso y balance?", options: ["El plano de referencia desde el cual se realizan todas las mediciones.", "El centro de gravedad.", "La estación del tren principal."], correctIndex: 0, explanation: "El datum es el plano vertical imaginario de referencia desde el cual se realizan todas las mediciones horizontales (brazos) para el peso y balance. No es el centro de gravedad ni la estación del tren principal.", cite: "PHAK Cap. 10 (weight and balance)" },
  { id: "q_laof_1_125", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué representa el arm en peso y balance?", options: ["La distancia entre el datum y el centro de gravedad de un elemento.", "La distancia entre ambas alas.", "El peso máximo autorizado."], correctIndex: 0, explanation: "El arm (brazo) es la distancia horizontal desde el datum hasta el centro de gravedad del elemento considerado. Multiplicado por el peso produce el momento; no es una distancia entre alas ni un peso máximo.", cite: "PHAK Cap. 10 (weight and balance)" },
  { id: "q_laof_1_126", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué representa el momento (moment) en peso y balance?", options: ["El producto del peso por el brazo (arm).", "El centro de gravedad longitudinal.", "La suma de todos los pesos."], correctIndex: 0, explanation: "El momento es el producto del peso de un elemento por su brazo (peso × distancia al datum), expresado en lb-in. La suma de momentos dividida entre el peso total da la posición del CG.", cite: "PHAK Cap. 10 (weight and balance)" },
  { id: "q_laof_1_127", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el objetivo principal del cálculo de peso y balance?", options: ["Reducir el consumo de combustible.", "Mantener el centro de gravedad dentro de los límites establecidos.", "Incrementar la velocidad de crucero."], correctIndex: 1, explanation: "El objetivo principal del cálculo de peso y balance es asegurar que el peso no exceda los límites y que el centro de gravedad se mantenga dentro de la envolvente aprobada, condición esencial de estabilidad y control. La reducción de consumo o el aumento de crucero son efectos secundarios, no el objetivo.", cite: "PHAK Cap. 10 (weight and balance)" },
  { id: "q_laof_2_128", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué efecto tiene el incremento del factor de carga sobre la estructura de la aeronave?", options: ["Reduce automáticamente el peso efectivo.", "Incrementa los esfuerzos estructurales soportados por la aeronave.", "Disminuye la resistencia inducida."], correctIndex: 1, explanation: "El factor de carga expresa cuántas veces el peso soporta la estructura: un factor de 3 significa que la carga total sobre la estructura es tres veces el peso (3 G). Por eso, aumentar el factor de carga incrementa los esfuerzos estructurales. No reduce el peso efectivo (lo multiplica) ni disminuye la resistencia inducida (a mayor G se requiere más sustentación y la resistencia inducida aumenta).", cite: "PHAK Cap. 5 (Load Factors, 5-33)" },
  { id: "q_laof_2_129", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Cuál es el propósito principal de las superficies anti-servo instaladas en algunas aeronaves?", options: ["Eliminar la necesidad de compensadores.", "Reducir el esfuerzo sobre los pedales del timón de dirección.", "Incrementar el esfuerzo necesario para mover una superficie totalmente móvil."], correctIndex: 2, explanation: "El PHAK indica que los estabilizadores totalmente móviles (stabilators) llevan una aleta antiservo que se mueve en el mismo sentido que el borde de salida de la superficie, haciéndola menos sensible, es decir, aumentando artificialmente el esfuerzo del piloto para evitar sobre-controlar. No elimina compensadores (de hecho también funciona como trim tab) ni actúa sobre los pedales del timón.", cite: "PHAK Cap. 6 (Antiservo Tabs, 6-11; 'helps make the stabilator less sensitive')" },
  { id: "q_laof_2_130", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "¿Qué efecto produce el barrido alar (wing sweep) a velocidades elevadas?", options: ["Retrasa la aparición de los efectos de compresibilidad.", "Incrementa considerablemente la resistencia inducida.", "Reduce el efecto del viento cruzado durante el aterrizaje."], correctIndex: 0, explanation: "El PHAK es literal: 'Sweepback is incorporated in the design of the wing primarily to delay the onset of compressibility during high-speed flight' — el ala en flecha reduce la componente de velocidad perpendicular al borde de ataque y eleva el Mach crítico. No se instala para aumentar resistencia inducida ni tiene relación con el viento cruzado en el aterrizaje.", cite: "PHAK Cap. 5 (p. 5-19, Sweepback) y Cap. 5 High-Speed Flight" },
  { id: "q_laof_2_131", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "¿Qué condición favorece la formación de ondas de montaña?", options: ["Viento débil con atmósfera inestable.", "Niebla de radiación durante la noche.", "Viento fuerte que cruza perpendicularmente una cordillera en una atmósfera estable."], correctIndex: 2, explanation: "Las ondas de montaña se forman cuando un viento fuerte (típicamente ≥40 kt) sopla perpendicular a una cordillera en aire estable: el aire desciende por sotavento y oscila formando ondas con turbulencia y rotores. Con aire inestable la energía se disipa en convección y no se forman ondas organizadas; la niebla de radiación es un fenómeno de aire calmo, sin relación.", cite: "PHAK Cap. 12 (Weather Theory, Fig. 12-16) / AC 00-6B (mountain waves: viento fuerte perpendicular + aire estable)" },
  { id: "q_laof_2_132", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "¿Cuál es el principal beneficio de mantener una adecuada conciencia situacional?", options: ["Incrementar automáticamente la autonomía de combustible.", "Eliminar la necesidad de listas de verificación.", "Permitir una mejor toma de decisiones y reducir la probabilidad de errores."], correctIndex: 2, explanation: "El PHAK define la conciencia situacional como la percepción y comprensión precisa de todos los factores y condiciones que afectan la seguridad antes, durante y después del vuelo; su beneficio es una mejor toma de decisiones (ADM) y menor probabilidad de error. No aumenta la autonomía ni sustituye a las listas de verificación, que siguen siendo obligatorias.", cite: "PHAK Cap. 2 (Aeronautical Decision-Making — Situational Awareness)" },
  { id: "q_laof_2_133", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa IFR?", options: ["Instrument Flight Rules", "Instrument Following Rules", "IMC Flight Rules."], correctIndex: 0, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, IFR = Instrument Flight Rules. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('IFR: Instrument Flight Rules')" },
  { id: "q_laof_2_134", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa VFR?", options: ["VMC Flight Rules.", "Visual Following Rules.", "Visual Flight Rules."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, VFR = Visual Flight Rules. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('VFR: Visual Flight Rules')" },
  { id: "q_laof_2_135", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa IMC?", options: ["Instrument Monitoring and Comparating.", "Instrument Meteorological Capabilities.", "Instrument Meteorological Conditions."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, IMC = Instrument Meteorological Conditions. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('IMC: Instrument Meteorological Conditions')" },
  { id: "q_laof_2_136", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa VMC?", options: ["Visual Monitoring and Comparating.", "Visual Meteorological Condition.", "Visual Meteorological Capabilities."], correctIndex: 1, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, VMC = Visual Meteorological Conditions. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('VMC: Visual Meteorological Conditions')" },
  { id: "q_laof_2_137", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa MHA?", options: ["Minimum Height of Approach.", "Maximum Holding Altitude.", "Minimum Holding Altitude."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, MHA = Minimum Holding Altitude. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('MHA: Minimum Holding Altitude')" },
  { id: "q_laof_2_138", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa ACAS?", options: ["Attitude and Compass Adjustment System.", "Airborne Collision Avoidance System.", "Altitude Compensation Adjustement System."], correctIndex: 1, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, ACAS = Airborne Collision Avoidance System. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('ACAS: Airborne Collision Avoidance System')" },
  { id: "q_laof_2_139", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa ACFT?", options: ["Airplane.", "Aircraft Collision-Terrain System.", "Aircraft."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, ACFT = Aircraft. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('ACFT: Aircraft')" },
  { id: "q_laof_2_140", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa ARTCC?", options: ["Artic Zone Control Center.", "Aircraft Repeated-Transponder Control Center.", "Air Route Traffic Control Center."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, ARTCC = Air Route Traffic Control Center. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('ARTCC: Air Route Traffic Control Center')" },
  { id: "q_laof_2_141", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa ATCC?", options: ["Air Traffic Control-ClassC airspace.", "Air Traffic Control Controller.", "Air Traffic Control Center."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, ATCC = Air Traffic Control Center. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('ATCC: Air Traffic Control Center')" },
  { id: "q_laof_2_142", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa ATCT?", options: ["Air Traffic Control Tower", "Air Traffic Control Terminal área.", "Air Traffic Control Transponder Frequency."], correctIndex: 0, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, ATCT = Air Traffic Control Tower. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('ATCT: Air Traffic Control Tower')" },
  { id: "q_laof_2_143", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa ATIS?", options: ["Automatic Terminal Information System.", "Automated Terminal Information System.", "Automatic Terminal Information Service."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, ATIS = Automatic Terminal Information Service. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('ATIS: Automatic Terminal Information Service')" },
  { id: "q_laof_2_144", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa B-RNAV?", options: ["B-Class Airspace RNAV.", "Ground-Based RNAV.", "Basic RNAV."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, B-RNAV = Basic RNAV. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('B-RNAV: Basic RNAV')" },
  { id: "q_laof_2_145", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa CDFA?", options: ["Class-D Airspace Frequency.", "Continuous Descent Final Approach.", "Clearance Delivery Frequency."], correctIndex: 1, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, CDFA = Continuous Descent Final Approach. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('CDFA: Continuous Descent Final Approach')" },
  { id: "q_laof_2_146", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa CDI?", options: ["Course Deviation Indicator", "Course Deviation Input.", "Course Deviation ILS."], correctIndex: 0, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, CDI = Course Deviation Indicator. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('CDI: Course Deviation Indicator')" },
  { id: "q_laof_2_147", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa CFIT?", options: ["Controlled Flight Into Terrain.", "Controlled Flight Into Thunderstoms.", "Controlled Flight Into Traffic."], correctIndex: 0, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, CFIT = Controlled Flight Into Terrain. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('CFIT: Controlled Flight Into Terrain')" },
  { id: "q_laof_2_148", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa COP?", options: ["Change Over Point.", "Course Over PVOR.", "Course Over Point."], correctIndex: 0, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, COP = Change Over Point. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('COP: Change Over Point')" },
  { id: "q_laof_2_149", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa D-ATIS?", options: ["D-Class Airspace ATIS.", "Direct ATIS.", "Digital ATIS."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, D-ATIS = Digital ATIS. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('D-ATIS: Digital ATIS')" },
  { id: "q_laof_2_150", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa DCL?", options: ["Direct Clearance Limit.", "Data Link Departure Clearance Service.", "Direct Course Locator."], correctIndex: 1, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, DCL = Data Link Departure Clearance Service. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('DCL: Data Link Departure Clearance Service')" },
  { id: "q_laof_2_151", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa FIR?", options: ["Fix Intermediate.", "Flight Information Radar Service.", "Flight Information Region."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, FIR = Flight Information Region. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('FIR: Flight Information Region')" },
  { id: "q_laof_2_152", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa GNSS?", options: ["Global Navigation Satellite System.", "Global Navigation Safety System.", "General Navigation Satellite System."], correctIndex: 0, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, GNSS = Global Navigation Satellite System. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('GNSS: Global Navigation Satellite System')" },
  { id: "q_laof_2_153", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa GPWS?", options: ["Global Positioning System.", "General Positioning Warning System.", "Ground Proximity Warning System."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, GPWS = Ground Proximity Warning System. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('GPWS: Ground Proximity Warning System')" },
  { id: "q_laof_2_154", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa HST?", options: ["High Speed Taxiway Turnoff.", "High Speed Taxi.", "High Speed Takeoff."], correctIndex: 0, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, HST = High Speed Taxiway Turn-off. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('HST: High Speed Taxiway Turn-off')" },
  { id: "q_laof_2_155", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa IAF?", options: ["Intermediate Approach Fix.", "Initial Approach Fix.", "Initial Approach Frequency."], correctIndex: 1, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, IAF = Initial Approach Fix. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('IAF: Initial Approach Fix')" },
  { id: "q_laof_2_156", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa LAAS?", options: ["Low-level Aircraft Awareness System.", "Lateral Avoidance Anticollision System.", "Local Area Augmentation System."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, LAAS = Local Area Augmentation System. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('LAAS: Local Area Augmentation System')" },
  { id: "q_laof_2_157", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa LDA?", options: ["Landing Distance Acquired.", "Landing Distance Anticipated.", "Landing Distance Available."], correctIndex: 2, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, LDA = Landing Distance Available. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('LDA: Landing Distance Available')" },
  { id: "q_laof_2_158", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa LLWAS?", options: ["Low Level Wide Augmentation System.", "Low Level Wind Shear Alert System.", "Low Limit Wide Augmentation System."], correctIndex: 1, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, LLWAS = Low Level Wind Shear Alert System. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('LLWAS: Low Level Wind Shear Alert System')" },
  { id: "q_laof_2_159", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa LNAV?", options: ["Low Level Navigation.", "Lateral Navigation.", "Longitudinal Navigation."], correctIndex: 1, explanation: "En la lista oficial 'Abbreviations Used in Airway Manual' del Jeppesen Introduction, LNAV = Lateral Navigation. Los distractores son expansiones inventadas que no figuran en la lista de abreviaturas de Jeppesen ni en la terminología OACI/FAA.", cite: "Jeppesen Intro — Definitions and Abbreviations ('LNAV: Lateral Navigation')" },
  { id: "q_laof_2_160", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa en español ETD?", options: ["Tiempo estimado en ruta.", "Hora estimada de salida.", "Hora real de llegada."], correctIndex: 1, explanation: "ETD = Estimated Time of Departure, es decir, hora estimada de salida. ETE es el tiempo estimado en ruta y ATA la hora real de llegada, por lo que ambos distractores corresponden a otras siglas.", cite: "Jeppesen Intro — Abbreviations ('ETD: Estimated Time of Departure')" },
  { id: "q_laof_2_161", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa en español ATD?", options: ["Hora estimada de salida.", "Hora real de salida.", "Tiempo estimado en ruta."], correctIndex: 1, explanation: "ATD = Actual Time of Departure, hora real de salida. La 'A' de Actual la distingue de ETD (estimada); ETE es el tiempo estimado en ruta.", cite: "Jeppesen Intro — Abbreviations ('ATD: Actual Time of Departure')" },
  { id: "q_laof_2_162", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa en español ETA?", options: ["Hora real de llegada.", "Hora estimada de llegada.", "Tiempo estimado en ruta."], correctIndex: 1, explanation: "ETA = Estimated Time of Arrival, hora estimada de llegada. La hora real de llegada es ATA y el tiempo estimado en ruta es ETE.", cite: "Jeppesen Intro — Abbreviations ('ETA: Estimated Time of Arrival')" },
  { id: "q_laof_2_163", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa en español ATA?", options: ["Hora estimada de llegada.", "Hora real de llegada.", "Tiempo estimado en ruta."], correctIndex: 1, explanation: "ATA = Actual Time of Arrival, hora real de llegada. La estimada es ETA; el tiempo en ruta es ETE.", cite: "Jeppesen Intro — Abbreviations ('ATA: Actual Time of Arrival')" },
  { id: "q_laof_2_164", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa en español ETE?", options: ["Tiempo estimado en ruta.", "Hora real de llegada.", "Hora estimada de llegada."], correctIndex: 0, explanation: "ETE = Estimated Time En route, tiempo estimado en ruta (duración del tramo), no una hora de reloj como ATA (real de llegada) o ETA (estimada de llegada).", cite: "Jeppesen Intro — Abbreviations ('ETE: Estimated Time En Route')" },
  { id: "q_laof_2_165", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa ADIZ?", options: ["Automatic Defense Identification Zone.", "Air Defense Identification Zone.", "Automatic Data Integration Zone."], correctIndex: 1, explanation: "La lista de abreviaturas Jeppesen define ADIZ = Air Defense Identification Zone (zona de identificación de defensa aérea). Los distractores sustituyen 'Air' por 'Automatic', expansión que no existe.", cite: "Jeppesen Intro — Abbreviations ('ADIZ: Air Defense Identification Zone')" },
  { id: "q_laof_2_166", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa ALS?", options: ["Approach Light System.", "Approach and Landing System.", "Approach and Landing Step-out procedure."], correctIndex: 0, explanation: "ALS = Approach Light System (sistema de luces de aproximación), familia a la que pertenecen ALSF, MALS, SALS, etc. No es un sistema de 'aproximación y aterrizaje'.", cite: "Jeppesen Intro — Abbreviations ('ALS: Approach Light System')" },
  { id: "q_laof_2_167", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa REIL?", options: ["Runway End Identifier Localizer.", "Runway Edge ILS Localizer.", "Runway End Identifier Lights."], correctIndex: 2, explanation: "REIL = Runway End Identifier Lights: dos destelladores sincronizados que identifican el umbral. La 'L' final es Lights, no Localizer.", cite: "Jeppesen Intro — Abbreviations ('REIL: Runway End Identifier Lights')" },
  { id: "q_laof_2_168", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa SALSF?", options: ["Simplified Approach Light System with Symmetric Flashing lights.", "Short Approach Light System with Sequenced Flashing lights.", "Short Approach Landing System with Sequenced Flashing lights."], correctIndex: 1, explanation: "SALSF = Short Approach Light System with Sequenced Flashing Lights según la lista Jeppesen. Es un sistema de luces (Light System), no de aterrizaje (Landing System), y los destellos son secuenciados, no simétricos.", cite: "Jeppesen Intro — Abbreviations ('SALSF: Short Approach Light System with Sequenced Flashing Lights')" },
  { id: "q_laof_2_169", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa SALS?", options: ["Short Approach Light System.", "Short Approach Landing Sequencing.", "Short Approach Landing System."], correctIndex: 0, explanation: "SALS = Short Approach Light System (versión corta del ALS). Los distractores cambian Light System por Landing System/Sequencing, expansiones inexistentes.", cite: "Jeppesen Intro — Abbreviations ('SALS: Short Approach Light System')" },
  { id: "q_laof_2_170", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa MIRL?", options: ["Medium Intensity Runway Edge Lights.", "Minimum Intensity Runway Lights.", "Maximum Intensity Runway Lights."], correctIndex: 0, explanation: "MIRL = Medium Intensity Runway Edge Lights (luces de borde de pista de intensidad media). La M es Medium, no Minimum/Maximum.", cite: "Jeppesen Intro — Abbreviations ('MIRL: Medium Intensity Runway Edge Lights')" },
  { id: "q_laof_2_171", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa HIRL?", options: ["High Intensity Runway end Lights.", "High Intensity Runway Lamps.", "High Intensity Runway Edge Lights."], correctIndex: 2, explanation: "HIRL = High Intensity Runway Edge Lights, luces de borde de pista de alta intensidad; son luces de borde, no de fin de pista.", cite: "Jeppesen Intro — Abbreviations ('HIRL: High Intensity Runway Edge Lights')" },
  { id: "q_laof_2_172", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa RCLM?", options: ["Runway Course Limit Monitoring.", "Runway Center Line Markings.", "Runway Center Line Metering."], correctIndex: 1, explanation: "RCLM = Runway Center Line Markings (marcas de eje de pista) según la lista Jeppesen; no existe 'monitoring/metering' de eje de pista.", cite: "Jeppesen Intro — Abbreviations ('RCLM: Runway Center Line Markings')" },
  { id: "q_laof_2_173", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa TDZE?", options: ["Touchdown Zulu Estimated", "Touchdown Zone Height.", "Touchdown Zone Elevation."], correctIndex: 2, explanation: "TDZE = Touchdown Zone Elevation: elevación más alta de los primeros 3,000 ft de pista, publicada en las cartas de aproximación. Es elevación (MSL), no altura (height).", cite: "Jeppesen Intro — Abbreviations ('TDZE: Touchdown Zone Elevation')" },
  { id: "q_laof_2_174", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa APAPI?", options: ["Abbreviated Precision Approach Path Indicator.", "Adjusted Precision Approach Path Indicator.", "Actual Precision Approach Path Indicator."], correctIndex: 0, explanation: "APAPI = Abbreviated Precision Approach Path Indicator, versión abreviada (2 luces) del PAPI. La A inicial es Abbreviated.", cite: "Jeppesen Intro — Abbreviations ('APAPI: Abbreviated Precision Approach Path Indicator')" },
  { id: "q_laof_2_175", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa PAPI?", options: ["Precision And Positioning Indicator.", "Precision Angle Path Indicator.", "Precision Approach Path Indicator."], correctIndex: 2, explanation: "PAPI = Precision Approach Path Indicator, indicador visual de senda de aproximación de 4 luces en fila. Las otras expansiones no existen.", cite: "Jeppesen Intro — Abbreviations ('PAPI: Precision Approach Path Indicator')" },
  { id: "q_laof_2_176", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa VASI?", options: ["Visual Approach Slope on ILS.", "Visual And Sight Indicator.", "Visual Approach Slope Indicator."], correctIndex: 2, explanation: "VASI = Visual Approach Slope Indicator, indicador visual de pendiente de aproximación (barras rojas/blancas). No depende del ILS.", cite: "Jeppesen Intro — Abbreviations ('VASI: Visual Approach Slope Indicator')" },
  { id: "q_laof_2_177", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa HIALS?", options: ["High Intensity Approach Light System.", "High-Intermediate Approach Light System.", "Height Increased Approach Light System."], correctIndex: 0, explanation: "HIALS = High Intensity Approach Light System, sistema de luces de aproximación de alta intensidad (figura además en el Charting Symbols Legend de Jeppesen).", cite: "Jeppesen Intro — Abbreviations ('HIALS: High Intensity Approach Light System')" },
  { id: "q_laof_2_178", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa MIALS?", options: ["Medium and Intermittend Approach Light System.", "Monitored Intensity Approach Light System.", "Medium Intensity Approach Light System."], correctIndex: 2, explanation: "MIALS = Medium Intensity Approach Light System según la lista Jeppesen; intensidad media, no 'intermitente' ni 'monitoreada'.", cite: "Jeppesen Intro — Abbreviations ('MIALS: Medium Intensity Approach Light System')" },
  { id: "q_laof_2_179", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa FAF?", options: ["Final Approach Fix.", "Final Arrival Fix.", "Final Alignment Frequency."], correctIndex: 0, explanation: "FAF = Final Approach Fix: fijo desde el que se ejecuta la aproximación final y que marca el inicio del segmento final; en cartas Jeppesen de no-precisión se identifica con la cruz de Malta.", cite: "Jeppesen Intro — Glossary ('FINAL APPROACH FIX (FAF)')" },
  { id: "q_laof_2_180", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa MAP o MAPt?", options: ["Maximum Approach Procedure.", "Missed Approach Point.", "Minimum Approach Path."], correctIndex: 1, explanation: "MAP/MAPt = Missed Approach Point, punto de una aproximación por instrumentos en el cual, de no tener referencia visual, debe iniciarse el procedimiento de aproximación fallida.", cite: "Jeppesen Intro — Glossary/Abbreviations ('MAP: Missed Approach Point')" },
  { id: "q_laof_2_181", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa MSA?", options: ["Minimum Sector Altitude.", "Maximum Safe Altitude.", "Minimum Separation Area."], correctIndex: 0, explanation: "MSA = Minimum Safe/Sector Altitude: altitud mínima que da 1,000 ft de libramiento de obstáculos dentro de 25 NM del fijo/navaid de referencia, dividida usualmente en sectores. Es mínima, no máxima.", cite: "Jeppesen Intro — Abbreviations ('MSA: Minimum Safe/Sector Altitude')" },
  { id: "q_laof_2_182", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa MEA?", options: ["Maximum Enroute Altitude.", "Minimum Enroute Altitude.", "Minimum Emergency Altitude."], correctIndex: 1, explanation: "MEA = Minimum Enroute Altitude: altitud mínima en ruta que garantiza recepción de señal de navegación y libramiento de obstáculos en el segmento de aerovía.", cite: "Jeppesen Intro — Abbreviations ('MEA: Minimum Enroute Altitude')" },
  { id: "q_laof_2_183", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa MOCA?", options: ["Minimum Obstacle Crossing Area.", "Maximum Obstruction Clearance Altitude.", "Minimum Obstruction Clearance Altitude."], correctIndex: 2, explanation: "MOCA = Minimum Obstruction Clearance Altitude: altitud mínima que asegura el libramiento de obstáculos en el segmento (con recepción VOR garantizada solo dentro de 22 NM en EUA). Es una altitud mínima, no máxima ni un área.", cite: "Jeppesen Intro — Abbreviations ('MOCA: Minimum Obstruction Clearance Altitude')" },
  { id: "q_laof_2_184", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa MORA?", options: ["Maximum Off-Route Altitude.", "Minimum Obstruction Required Area.", "Minimum Off-Route Altitude."], correctIndex: 2, explanation: "MORA = Minimum Off-Route Altitude (Grid o Route MORA en cartas Jeppesen): altitud mínima fuera de ruta que libra el terreno en el área cuadriculada o a 10 NM de la ruta. Es mínima, no máxima.", cite: "Jeppesen Intro — Abbreviations ('MORA: Minimum Off-Route Altitude (Grid or Route)')" },
  { id: "q_laof_2_185", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa OCA?", options: ["Obstacle Crossing Area.", "Obstacle Clearance Altitude.", "Obstacle Clearance Angle."], correctIndex: 1, explanation: "OCA = Obstacle Clearance Altitude: la altitud más baja (referida al MSL) que cumple los criterios de libramiento de obstáculos del procedimiento. Jeppesen la lista como OCA(H).", cite: "Jeppesen Intro — Abbreviations ('OCA (H): Obstacle Clearance Altitude (Height)')" },
  { id: "q_laof_2_186", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa OCH?", options: ["Obstacle Clearance Height.", "Obstacle Clearance Holding.", "Obstacle Crossing Height."], correctIndex: 0, explanation: "OCH = Obstacle Clearance Height: el mismo valor OCA pero referido a la elevación del umbral/aeródromo (altura). OACI publica el par OCA(H).", cite: "Jeppesen Intro — Abbreviations ('OCA (H): Obstacle Clearance Altitude (Height)') / Doc 8168" },
  { id: "q_laof_2_187", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa TAA?", options: ["Terminal Approach Altitude.", "Terminal Arrival Area.", "Traffic Advisory Area."], correctIndex: 1, explanation: "La lista Jeppesen define TAA = Terminal Arrival Area (FAA): áreas publicadas en procedimientos RNAV (típicamente en 'T') con altitudes mínimas por sector que sustituyen a la MSA.", cite: "Jeppesen Intro — Abbreviations ('TAA: Terminal Arrival Area (FAA)')" },
  { id: "q_laof_2_188", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa MAA?", options: ["Maximum Authorized Altitude.", "Minimum Arrival Altitude.", "Maximum Approach Altitude."], correctIndex: 0, explanation: "MAA = Maximum Authorized Altitude: altitud máxima autorizada en un segmento de aerovía (por ejemplo, para evitar recepción ambigua de dos navaids en la misma frecuencia).", cite: "Jeppesen Intro — Abbreviations ('MAA: Maximum Authorized Altitude')" },
  { id: "q_laof_2_189", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa OROCA?", options: ["Off-Route Obstruction Clearance Altitude.", "Operational Route Obstacle Clearance Area.", "Obstacle Route Operational Clearance Altitude."], correctIndex: 0, explanation: "OROCA = Off-Route Obstruction Clearance Altitude (término FAA, análogo del Grid MORA): da 1,000 ft de libramiento en terreno normal y 2,000 ft en montaña, fuera de aerovías.", cite: "FAA Pilot/Controller Glossary; equivalente Jeppesen: Grid MORA (Jeppesen Intro — Glossary)" },
  { id: "q_laof_2_190", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa RVR?", options: ["Radar Visibility Reference.", "Runway Visibility Report.", "Runway Visual Range."], correctIndex: 2, explanation: "RVR = Runway Visual Range: alcance visual en la pista medido por transmisómetros, usado en mínimos de despegue y aproximación. No es un reporte ni una referencia radar.", cite: "Jeppesen Intro — Abbreviations ('RVR: Runway Visual Range')" },
  { id: "q_laof_2_191", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa TCH?", options: ["Threshold Crossing Height.", "Touchdown Clearance Height.", "Terminal Crossing Height."], correctIndex: 0, explanation: "TCH = Threshold Crossing Height: altura a la que la senda de planeo (o la trayectoria VNAV) cruza el umbral de la pista, publicada en el perfil de las cartas de aproximación.", cite: "Jeppesen Intro — Abbreviations ('TCH: Threshold Crossing Height')" },
  { id: "q_laof_2_192", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa VDP?", options: ["Vertical Descent Path.", "Visual Descent Point.", "Visual Decision Procedure."], correctIndex: 1, explanation: "VDP = Visual Descent Point: punto en una aproximación de no-precisión desde el cual puede iniciarse el descenso desde la MDA con referencias visuales manteniendo una senda normal.", cite: "Jeppesen Intro — Abbreviations ('VDP: Visual Descent Point')" },
  { id: "q_laof_2_193", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa MDA?", options: ["Missed Descent Altitude.", "Minimum Decision Altitude.", "Minimum Descent Altitude."], correctIndex: 2, explanation: "MDA = Minimum Descent Altitude: altitud mínima de descenso en aproximaciones de no-precisión, por debajo de la cual no se desciende sin referencia visual. No confundir con DA (decisión), propia de aproximaciones con guía vertical.", cite: "Jeppesen Intro — Abbreviations ('MDA: Minimum Descent Altitude')" },
  { id: "q_laof_2_194", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa DA?", options: ["Departure Altitude.", "Decision Altitude.", "Descent Altitude."], correctIndex: 1, explanation: "DA = Decision Altitude: altitud (MSL) en una aproximación de precisión/APV en la que debe decidirse continuar visual o irse al aire.", cite: "Jeppesen Intro — Abbreviations ('DA: Decision Altitude')" },
  { id: "q_laof_2_195", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa DH?", options: ["Descent Height.", "Departure Height.", "Decision Height."], correctIndex: 2, explanation: "DH = Decision Height: el mismo punto de decisión pero expresado como altura sobre el umbral (se usa en CAT II/III con radioaltímetro).", cite: "Jeppesen Intro — Abbreviations ('DH: Decision Height')" },
  { id: "q_laof_2_196", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa IF?", options: ["Instrument Fix.", "Initial Final.", "Intermediate Fix."], correctIndex: 2, explanation: "IF = Intermediate Fix: fijo que marca el inicio del segmento intermedio de una aproximación por instrumentos, entre el IAF y el FAF.", cite: "Jeppesen Intro — Abbreviations ('IF: Intermediate Fix') / Doc 8168" },
  { id: "q_laof_2_197", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿A qué corresponde el siguiente símbolo?", options: ["A un LOC Back Course.", "A un ILS o LOC", "A un LOC o LOC Back Course."], correctIndex: 1, explanation: "La figura del banco es la 'pluma' alargada con achurado diagonal, que en el Charting Symbols Legend de Jeppesen corresponde a 'ILS, LOC, LDA, SDF, MLS or KRM (Front Course)', es decir, un curso frontal de ILS o LOC. El LOC Back Course se dibuja distinto (pluma delgada acompañada de la caja 'LOC (BACK CRS)' con el curso frontal anotado), por lo que las opciones A y C fallan.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 127 (NAVAIDS: 'ILS, LOC, LDA, SDF, MLS, or KRM (Front Course)')" },
  { id: "q_laof_2_198", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué diferencia hay entre el símbolo de arriba y el de abajo que se presentan a continuación?", options: ["La figura de arriba es un VOR mientras que la de abajo es un VORDME/VORTAC.", "Ambos son VORDME/VORTAC pero el de arriba es de bajo alcance (L) mientras que la de abajo es de alto alcance (H).", "Ambos son VORDME/VORTAC pero el de arriba es de reporte no-obligatorio y el de abajo es de reporte obligatorio."], correctIndex: 2, explanation: "Ambas figuras son la rosa graduada con cuadrado central (símbolo Jeppesen de VORDME/VORTAC); la diferencia es el relleno: el legend muestra el símbolo con centro relleno bajo la etiqueta 'Compulsory' (punto de reporte obligatorio) y el de centro vacío como no-obligatorio. La clase L/H no se distingue por el dibujo sino por la letra (L)/(H) dentro de la caja de datos del navaid, y un VOR simple no lleva el cuadrado central.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 126 (VORDME/VORTAC; símbolos rellenos marcados 'Compulsory')" },
  { id: "q_laof_2_199", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa el siguiente símbolo?", options: ["Fijo de aproximación final en un procedimiento de no-precisión.", "Fijo de aproximación final en un procedimiento de precisión.", "Fijo de aproximación fallida."], correctIndex: 0, explanation: "La figura es la cruz de Malta, que Jeppesen usa exclusivamente para el FAF de aproximaciones de no-precisión: el Glossary dice que el FAF 'is designated in the profile view of Jeppesen Terminal charts by the Maltese Cross symbol for non-precision approaches'. En precisión el punto final es el FAP (intercepción de la senda de planeo) y el fijo de fallida se rotula con 'M'.", cite: "Jeppesen Intro — Glossary ('FINAL APPROACH FIX') y Charting Symbols Legend, p. 133 ('Non Precision Final Approach Fix')" },
  { id: "q_laof_2_200", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Por qué no se encuentra encerrado en un recuadro el nombre, frecuencia e identificación del siguiente ejemplo?", options: ["Porque corresponde a un VOR de baja frecuencia.", "Porque son de uso en procedimientos de aproximación fallida y en inserciones que no están a escala.", "Porque no es relevante para el procedimiento publicado."], correctIndex: 1, explanation: "El ejemplo (HIGGINS 115.4 DUG sin recuadro) aparece tal cual en el Charting Symbols Legend con la nota 'Symbol used in missed approach and Not-to-scale insets': los navaids sin caja se usan en la aproximación fallida o en inserciones fuera de escala. Un VOR opera en VHF (no 'baja frecuencia') y sí es relevante, pues se publica precisamente para el procedimiento.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 126 (VOR: 'Symbol used in missed approach and Not-to-scale insets')" },
  { id: "q_laof_2_201", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿A qué corresponde el siguiente símbolo?", options: ["A un VORDME.", "A un VORTAC.", "A un DME."], correctIndex: 2, explanation: "La figura (círculo dentado con la caja 'JACOB DME-56 JAC (111.9)') es el ejemplo literal de la categoría DME del Charting Symbols Legend de Jeppesen. Un VORDME/VORTAC se dibuja como rosa graduada con centro cuadrado, no como círculo dentado con identificación 'DME-'.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 127 (DME: ejemplo 'JACOB DME-56 JAC (111.9)')" },
  { id: "q_laof_2_202", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿A qué corresponde la siguiente figura?", options: ["A un MM.", "A un NDB con capacidad de DME.", "A un LOM."], correctIndex: 2, explanation: "La figura (símbolo punteado de radiofaro con la caja 'BLAZEK 260 JB') aparece en el legend bajo NDB/LOCATOR con la nota 'Locator co-located with a Marker (LOM)': es un radiofaro localizador ubicado en el marcador exterior. Un MM se dibuja como elipse de marcador y el DME agregaría 'DME' a la identificación.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 127 (NDB/Locator: 'BLAZEK 260 JB — Locator co-located with a Marker (LOM)')" },
  { id: "q_laof_2_203", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué diferencia hay entre las figuras presentadas a continuación?", options: ["El NDB de arriba no es de uso en la aerovía y el de abajo sí.", "La de arriba es un NDB de reporte no obligatorio y la de abajo es obligatorio.", "La figura de arriba representa un NDB no monitoreado mientras que el de abajo sí lo está."], correctIndex: 1, explanation: "Ambos son símbolos de NDB (círculo punteado); en el legend de Jeppesen el NDB con centro relleno aparece rotulado 'Compulsory' (punto de reporte obligatorio) y el de centro vacío es no-obligatorio, igual que ocurre con los VOR/VORTAC y los fijos triangulares. El monitoreo o el uso en aerovía no se codifican mediante el relleno del símbolo.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 127 (NDB: símbolo relleno = 'Compulsory')" },
  { id: "q_laof_2_204", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿La numeración de la siguiente pista y su rumbo son conforme a?", options: ["Norte verdadero.", "Norte magnético.", "De acuerdo a la variación magnética."], correctIndex: 1, explanation: "El legend de Jeppesen (categoría AIRPORT, 'Runway Number') indica: 'Runway number is magnetic unless followed by T for true in far north' — la numeración (27/267°) es magnética salvo que lleve la letra T. Por eso A es falsa y C es un distractor impreciso: el número ya está referido al norte magnético, no 'a la variación'.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 129 ('Runway Number... magnetic unless followed by T for true')" },
  { id: "q_laof_2_205", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa la barra blanca en la siguiente figura?", options: ["Que existe una línea de parada.", "Que establece el límite, seguido de una cifra en pies o metros, de una zona LAHSO.", "Que la pista tiene el umbral desplazado."], correctIndex: 2, explanation: "En el Charting Symbols Legend (categoría AIRPORT) la pista dibujada como barra negra con una barra blanca transversal es exactamente el símbolo 'Displaced Threshold': la barra blanca marca el umbral desplazado. Los puntos LAHSO se dibujan con cajas rotuladas 'LAHSO' y flechas ('LAHSO Distance Points'), no con una barra blanca.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 130 ('Displaced Threshold') y p. 131 ('LAHSO Distance Points')" },
  { id: "q_laof_2_206", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa la siguiente figura?", options: ["Que las luces de aproximación se extienden al umbral desplazado.", "Que la superficie en tal porción de la pista no es apta para operaciones aéreas.", "Que en tal porción de la pista se alternan luces rojas y ámbar."], correctIndex: 0, explanation: "La figura (pista sólida seguida de un tramo en contorno con barras verticales interiores) coincide con el símbolo del legend 'Approach lights extending to displaced threshold'. La porción no utilizable se representa como 'Stopway/Overrun/Blast Pad' o 'Closed Runway' (con X), y el legend no codifica colores de luces en el plano de aeropuerto.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 130 ('Approach lights extending to displaced threshold')" },
  { id: "q_laof_2_207", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa la figura de la derecha?", options: ["Que el cono indicador de viento está co-localizado en un transmisor de RVR.", "Transmisor de fin de pista de RVR (rollout).", "Que el cono indicador de viento está iluminado."], correctIndex: 2, explanation: "En la categoría AIRPORT del legend, 'Wind Indicator' distingue 'Cone' (banderola simple, izquierda) y 'Lighted Cone' (banderola con rayos, derecha): la figura de la derecha es el cono iluminado. Los sitios de medición de RVR tienen su propio símbolo ('RVR Measuring Site') y no se combinan con el cono de viento.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 131 ('Wind Indicator: Cone / Lighted Cone')" },
  { id: "q_laof_2_208", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa la figura de la izquierda?", options: ["Que el cono indicador de viento no está co-localizado en un transmisor de RVR.", "Cono indicador de viento no-iluminado.", "Transmisor de fin de pista de RVR (rollout)."], correctIndex: 1, explanation: "Por el mismo legend, la banderola simple (sin rayos) es el 'Cone' sin iluminación, en contraste con el 'Lighted Cone' de la derecha. Las opciones sobre RVR mezclan un símbolo distinto ('RVR Measuring Site').", cite: "Jeppesen Intro — Charting Symbols Legend, p. 131 ('Wind Indicator: Cone / Lighted Cone')" },
  { id: "q_laof_2_209", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa la siguiente figura?", options: ["Indicador a partir del cual se puede continuar la ruta sin restricción (present position route).", "Que se requiere permiso previo de CTA en la dirección de la flecha mostrada.", "Indicador a partir del cual existe una zona prohibida para aviación comercial (prohibited route)."], correctIndex: 1, explanation: "La figura '◄PPR' es el símbolo 'Prior Permission Required' del legend de rutas y aerovías: 'Prior Permission Required from ATC for flight in direction of arrow' — se necesita autorización previa del control para volar en el sentido de la flecha. No existe en Jeppesen un 'present position route' ni un indicador de zona prohibida con esa forma.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 132 ('Prior Permission Required... in direction of arrow')" },
  { id: "q_laof_2_210", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa la siguiente figura?", options: ["Cambio de designador de aerovía.", "Sobrepaso de aerovía.", "Cambio de curso requerido."], correctIndex: 1, explanation: "La línea con un semicírculo (joroba) es el símbolo 'Airway By-Pass' del legend de rutas y aerovías: la aerovía sobrepasa (no utiliza) el fijo o navaid. El cambio de designador se muestra con las cajas del 'Airway Designator' y el cambio de rumbo sin fijo se marca con una X ('Mileage Break/CNF').", cite: "Jeppesen Intro — Charting Symbols Legend, p. 132 ('Airway By-Pass')" },
  { id: "q_laof_2_211", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa la siguiente figura?", options: ["Fijo RNAV de reporte obligatorio.", "Fijo RNAV de reporte no-obligatorio.", "Fijo RNAV en segmentos fuera de aerovías."], correctIndex: 1, explanation: "La estrella de cuatro puntas en contorno (sin rellenar) es el símbolo 'RNAV Non-Compulsory/CNF' del legend de fijos de espacio aéreo; la versión rellena es 'RNAV Compulsory' (reporte obligatorio). El relleno, no la posición respecto a la aerovía, es lo que codifica el tipo de reporte.", cite: "Jeppesen Intro — Charting Symbols Legend, p. 133 ('RNAV Non-Compulsory/CNF' vs 'RNAV Compulsory')" },
  { id: "q_laof_2_212", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Cuál es la ubicación de la aeronave de acuerdo con este signo?", options: ["La aeronave se encuentra en la pista 21, próxima al rodaje A.", "El rodaje A se encuentra a la izquierda de la aeronave y la pista 21 a la derecha de la aeronave.", "La aeronave se encuentra en el rodaje A, próxima a la cabecera de la pista 21."], correctIndex: 2, explanation: "El panel negro con letra amarilla 'A' es un letrero de ubicación (dónde estoy: rodaje A) y el panel rojo '21' es el letrero de posición de espera de la pista 21; juntos indican que la aeronave rueda por el rodaje A y está por llegar al punto de espera de la cabecera de la pista 21 (un solo número indica el extremo/umbral de esa pista). El letrero no indica estar sobre la pista ni direcciones izquierda/derecha.", cite: "Jeppesen Intro — United States Airport Sign Systems / PHAK Cap. 14 (location sign + runway holding position sign)" },
  { id: "q_laof_2_213", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Cuál es la ubicación de la aeronave de acuerdo con este signo?", options: ["La aeronave se encuentra en la pista 21-3, próxima al rodaje A.", "El rodaje A se encuentra a la izquierda de la aeronave y la pista 21-3 a la derecha de la aeronave.", "La aeronave se encuentra en el rodaje A, próxima a intersectar la pista 21-3."], correctIndex: 2, explanation: "El letrero de ubicación 'A' indica que la aeronave está en el rodaje A y el letrero rojo '21-3' es la posición de espera de una intersección con la pista 21-3: el umbral de la 21 queda hacia la izquierda y el de la 3 hacia la derecha del punto. La aeronave está en el rodaje, no sobre la pista, y el letrero describe la pista que va a cruzar, no la posición del rodaje.", cite: "Jeppesen Intro — United States Airport Sign Systems / PHAK Cap. 14 (runway holding position sign en intersección)" },
  { id: "q_laof_2_214", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa el siguiente signo?", options: ["Que está prohibido el ingreso de aeronaves.", "Que está prohibido el ingreso de vehículos.", "Que se está próximo al ingreso a una pista."], correctIndex: 0, explanation: "El panel rojo con círculo blanco y barra horizontal es el letrero 'No Entry': identifica un área a la que está prohibido que ingresen las aeronaves (por ejemplo, un rodaje de un solo sentido). No es un letrero vial para vehículos ni un aviso de proximidad de pista (ese es el letrero rojo con el número de pista).", cite: "Jeppesen Intro — United States Airport Sign Systems / PHAK Cap. 14 y AIM 2-3-8 (No Entry sign)" },
  { id: "q_laof_2_215", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa el siguiente signo?", options: ["Que quedan 2100 pies de pista remanente.", "Que la aeronave se encuentra en la pista 21.", "Que la longitud total de la pista es de 2100 metros."], correctIndex: 1, explanation: "El letrero negro con inscripción y borde amarillos '21' es un letrero de ubicación de pista (runway location sign): indica que la aeronave se encuentra sobre la pista 21. Los letreros de distancia remanente son negros con un solo dígito blanco que expresa miles de pies, por lo que '21' no puede ser distancia ni longitud.", cite: "Jeppesen Intro — United States Airport Sign Systems / PHAK Cap. 14 (runway location sign)" },
  { id: "q_laof_2_216", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significa el siguiente signo?", options: ["Que la aeronave se encuentra en la pista 3.", "Que la longitud total de la pista es de 3000 metros.", "Que quedan 3000 pies de pista remanente."], correctIndex: 2, explanation: "El panel negro con numeral blanco '3' es un letrero de distancia remanente (runway distance remaining sign): expresa la pista restante en miles de pies, aquí 3,000 ft. El letrero de ubicación de pista sería negro con caracteres amarillos, y ningún letrero indica la longitud total en metros.", cite: "Jeppesen Intro — United States Airport Sign Systems / PHAK Cap. 14 (runway distance remaining sign)" },
  { id: "q_laof_2_217", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significan estas marcas?", options: ["Indican el comienzo de una pista y la distancia utilizable para el despegue.", "Indican que el umbral de la pista está desplazado.", "Designan áreas que no son utilizables para rodaje, despegue o aterrizaje."], correctIndex: 2, explanation: "Las marcas amarillas en forma de chevrón (galones) identifican zonas de blast pad/stopway alineadas con la pista que NO son utilizables para rodar, despegar ni aterrizar. Las flechas blancas (no chevrones) son las que señalan un umbral desplazado, cuya área previa sí puede usarse para despegue.", cite: "PHAK Cap. 14 / AIM 2-3-3 (chevrons) y Jeppesen Intro — US Instrument Runway Markings" },
  { id: "q_laof_2_218", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿Qué significan estas marcas?", options: ["Indica que el umbral de la pista se encuentra desplazado.", "Delimita zonas que no son utilizables para rodaje, despegues y aterrizajes.", "Indican que la pista en las que se encuentra tiene un ILS."], correctIndex: 0, explanation: "Las flechas blancas centradas que conducen a una barra transversal (barra de umbral) son las marcas de umbral desplazado: la porción con flechas puede usarse para rodaje y comienzo de despegue, pero no para aterrizar. Las áreas inutilizables llevan chevrones amarillos y la marca de posición de espera ILS es la 'escalera' amarilla, distinta.", cite: "PHAK Cap. 14 / AIM 2-3-3 (displaced threshold) y Jeppesen Intro — US Instrument Runway Markings" },
  { id: "q_laof_2_219", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "JEPP", text: "¿De qué lado de la siguiente marca debe detenerse una aeronave?", options: ["De manera indistinta a cualquier lado.", "Antes del lado sólido (la aeronave rueda de arriba hacia abajo en la figura).", "Antes del lado con guiones (la aeronave rueda de abajo hacia arriba en la figura)."], correctIndex: 1, explanation: "En la marca de posición de espera de pista (dos líneas continuas y dos discontinuas), la aeronave que se aproxima por el lado de las líneas continuas debe detenerse antes de ellas; el lado de guiones queda hacia la pista y se cruza al salir de ella sin necesidad de autorización adicional. Por eso se sostiene B y no C: nunca se 'espera' del lado discontinuo.", cite: "PHAK Cap. 14 / AIM 2-3-5 (runway holding position markings: hold on the solid-line side)" },
  { id: "q_laof_2_220", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "De acuerdo al alfabeto fonético, ¿cómo se pronuncia la letra “M”?", options: ["Metro.", "Mike."], correctIndex: 1, explanation: "El alfabeto de deletreo radiotelefónico de la OACI (Anexo 10 Vol. II, 5.2.1.3 y Figura 5-1) asigna a la letra M la palabra 'Mike'. El distractor no pertenece al alfabeto OACI.", cite: "Annex 10 Vol II 5.2.1.3 (Radiotelephony spelling alphabet, Fig. 5-1)" },
  { id: "q_laof_2_221", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "De acuerdo al alfabeto fonético, ¿cómo se pronuncia la letra “N”?", options: ["November.", "Néctar."], correctIndex: 0, explanation: "El alfabeto de deletreo radiotelefónico de la OACI (Anexo 10 Vol. II, 5.2.1.3 y Figura 5-1) asigna a la letra N la palabra 'November'. El distractor no pertenece al alfabeto OACI.", cite: "Annex 10 Vol II 5.2.1.3 (Radiotelephony spelling alphabet, Fig. 5-1)" },
  { id: "q_laof_2_222", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "De acuerdo al alfabeto fonético, ¿cómo se pronuncia la letra “C”?", options: ["Coca.", "Charlie."], correctIndex: 1, explanation: "El alfabeto de deletreo radiotelefónico de la OACI (Anexo 10 Vol. II, 5.2.1.3 y Figura 5-1) asigna a la letra C la palabra 'Charlie'. El distractor no pertenece al alfabeto OACI.", cite: "Annex 10 Vol II 5.2.1.3 (Radiotelephony spelling alphabet, Fig. 5-1)" },
  { id: "q_laof_2_223", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "De acuerdo al alfabeto fonético, ¿cómo se pronuncia la letra “F”?", options: ["Fox.", "Foxtrot."], correctIndex: 1, explanation: "El alfabeto de deletreo radiotelefónico de la OACI (Anexo 10 Vol. II, 5.2.1.3 y Figura 5-1) asigna a la letra F la palabra 'Foxtrot'. El distractor no pertenece al alfabeto OACI.", cite: "Annex 10 Vol II 5.2.1.3 (Radiotelephony spelling alphabet, Fig. 5-1)" },
  { id: "q_laof_2_224", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "De acuerdo al alfabeto fonético, ¿cómo se pronuncia la letra “J”?", options: ["Juliett.", "Julieta."], correctIndex: 0, explanation: "El alfabeto de deletreo radiotelefónico de la OACI (Anexo 10 Vol. II, 5.2.1.3 y Figura 5-1) asigna a la letra J la palabra 'Juliett'. El distractor no pertenece al alfabeto OACI.", cite: "Annex 10 Vol II 5.2.1.3 (Radiotelephony spelling alphabet, Fig. 5-1)" },
  { id: "q_laof_2_225", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "De acuerdo al alfabeto fonético, ¿cómo se pronuncia la letra “X”?", options: ["X-ray.", "Extra."], correctIndex: 0, explanation: "El alfabeto de deletreo radiotelefónico de la OACI (Anexo 10 Vol. II, 5.2.1.3 y Figura 5-1) asigna a la letra X la palabra 'X-ray'. El distractor no pertenece al alfabeto OACI.", cite: "Annex 10 Vol II 5.2.1.3 (Radiotelephony spelling alphabet, Fig. 5-1)" },
  { id: "q_laof_2_226", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál de los siguientes reportes de posición radiotelefónicos es correcto?", options: ["Costera dos uno dos, posición ELOGO, sigue ASUTA uno tres tres cinco zulu, nivel de vuelo tres cinco cero.", "Costera dos uno dos, posición ELOGO, uno dos tres cuatro zulu, Mach decimal ocho cero; ASUTA uno tres tres cinco zulu.", "Costera dos uno dos, posición ELOGO, uno dos tres cuatro zulu, nivel de vuelo tres cinco cero; ASUTA uno tres tres cinco zulu, MIKKE."], correctIndex: 2, explanation: "El reporte de posición estándar contiene, en orden: identificación, posición, hora sobre la posición, nivel, siguiente posición con hora estimada y el punto significativo subsiguiente. Solo la opción C incluye los seis elementos (ELOGO, 1234Z, FL350, ASUTA 1335Z y MIKKE). A omite la hora sobre ELOGO y B omite el nivel (da solo Mach) y el punto subsiguiente.", cite: "PANS-ATM Doc 4444, 4.11 y Apéndice 1 (AIREP) / Annex 10 Vol II 5.2.2 (reproducido en la sección ATC del Jeppesen)" },
  { id: "q_laof_2_227", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál de los siguientes contactos iniciales es correcto posterior a un cambio de frecuencia?", options: ["Mérida Control, Costera dos uno dos en su frecuencia, nivelados a tres cinco cero.", "Mérida Control, Costera dos uno dos, nivel de vuelo tres cinco cero.", "Mérida Control, Costera dos uno dos con usted, nivelados tres cinco cero."], correctIndex: 1, explanation: "El contacto inicial tras un cambio de frecuencia se limita a: estación llamada, distintivo de llamada y nivel actual (con la altitud autorizada si se está en ascenso/descenso). Frases de relleno como 'en su frecuencia', 'con usted' o 'nivelados' no son fraseología estándar y deben evitarse; por eso A y C son incorrectas.", cite: "Annex 10 Vol II 5.2.1.7.3 (llamada) / Doc 4444 12.2.2; AIM 4-2-3 desaconseja 'with you'/'on frequency'" },
  { id: "q_laof_2_228", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es la fraseología correcta en inglés, cuando el piloto requiere indicar que no le es posible cumplir con una autorización o instrucción?", options: ["Unable.", "Not possible.", "Negative."], correctIndex: 0, explanation: "La tabla de palabras y frases normalizadas del Anexo 10 define UNABLE: 'I cannot comply with your request, instruction, or clearance', normalmente seguida de la razón. NEGATIVE significa 'no' o 'permiso no concedido' (responde a una pregunta, no a una instrucción) y 'Not possible' no es fraseología estándar.", cite: "Annex 10 Vol II 5.2.1.9 (tabla: UNABLE / NEGATIVE)" },
  { id: "q_laof_2_229", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es la fraseología correcta en inglés que el piloto requiere indicar cuando se inicia la desviación de una autorización o instrucción de CTA para cumplir con una resolución de ACAS?", options: ["TCAS climb/TCAS descent.", "TCAS maneuver in progress.", "TCAS RA."], correctIndex: 2, explanation: "La fraseología ACAS del Doc 4444 (12.3.1.2) establece que, al iniciar la desviación de la autorización por un aviso de resolución, el piloto notifica '(callsign) TCAS RA', y el ATC responde 'ROGER'. 'TCAS climb' y 'TCAS maneuver in progress' no son frases publicadas.", cite: "PANS-ATM Doc 4444 12.3.1.2 (ACAS: 'TCAS RA') — reproducido en la sección ATC del Jeppesen (Doc 8168 Airborne Surveillance)" },
  { id: "q_laof_2_230", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es la fraseología correcta en inglés que el piloto requiere hacer, posterior a una resolución ACAS, para indicar que regresa a una autorización asignada previamente?", options: ["Clear of traffic, returning to…", "Clear of conflict, returning to…", "Traffic no longer a factor, returning to.."], correctIndex: 1, explanation: "Tras completarse la maniobra por el RA, la fraseología publicada es '(callsign) CLEAR OF CONFLICT, RETURNING TO (assigned clearance)'. Las variantes 'clear of traffic' o 'traffic no longer a factor' no son las frases normalizadas del Doc 4444.", cite: "PANS-ATM Doc 4444 12.3.1.2 (ACAS: 'CLEAR OF CONFLICT, RETURNING TO...')" },
  { id: "q_laof_2_231", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es la fraseología correcta en inglés que el piloto requiere hacer para indicar una condición de combustible mínimo?", options: ["Fuel emergency.", "Minimum fuel.", "Fuel condition."], correctIndex: 1, explanation: "La declaración normalizada es 'MINIMUM FUEL': informa que, aceptando proceder al aeródromo previsto, cualquier demora adicional podría obligar a aterrizar con menos de la reserva final; no otorga prioridad. Si se prevé aterrizar por debajo de la reserva final se declara emergencia con 'MAYDAY MAYDAY MAYDAY FUEL', no 'fuel emergency' a secas.", cite: "PANS-ATM Doc 4444 12.3.1.2 (MINIMUM FUEL) / Annex 6" },
  { id: "q_laof_2_232", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es la fraseología correcta en inglés que el piloto requiere hacer para indicar de recibida información de tráfico?", options: ["Looking/Traffic in TCAS/negative contact.", "Looking out/Traffic in sight/negative contact.", "Looking for traffic/Traffic in TCAS/negative contact."], correctIndex: 1, explanation: "El Doc 4444 (12.3.1.2, información de tránsito) prevé como acuse del piloto: 'LOOKING OUT' (buscando), 'TRAFFIC IN SIGHT' (tráfico a la vista) o 'NEGATIVE CONTACT' (sin contacto visual). 'Traffic in TCAS' no es fraseología estándar: el contacto debe ser visual.", cite: "PANS-ATM Doc 4444 12.3.1.2 (Traffic information: LOOKING OUT / TRAFFIC IN SIGHT / NEGATIVE CONTACT)" },
  { id: "q_laof_2_233", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es la fraseología correcta en inglés que el piloto requiere hacer para indicar que turbulencia severa afecta la capacidad de la aeronave de mantener altitud de acuerdo a los requerimientos de RVSM?", options: ["Unable RVSM due instrument oscillations.", "Unable RVSM due turbulence.", "Negative RVSM, severe turbulence."], correctIndex: 1, explanation: "La fraseología RVSM del Doc 4444 (12.3.1.14) es 'UNABLE RVSM DUE TURBULENCE' para turbulencia severa que impide mantener la altitud con la precisión requerida. 'Negative RVSM' se usa solo para indicar que la aeronave no está aprobada RVSM, y 'instrument oscillations' no es una frase publicada.", cite: "PANS-ATM Doc 4444 12.3.1.14 (UNABLE RVSM DUE TURBULENCE)" },
  { id: "q_laof_2_234", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es la fraseología correcta en inglés que el piloto requiere hacer para indicar que los instrumentos se han degradado por debajo de los estándares mínimos de performance para RVSM?", options: ["Unable RVSM due to instrument failure.", "Negative RVSM, equipment failure.", "Unable RVSM due equipment."], correctIndex: 2, explanation: "Para degradación del equipo por debajo de los MASPS de RVSM la frase publicada es 'UNABLE RVSM DUE EQUIPMENT'. Las otras dos opciones parafrasean pero no corresponden al texto normalizado del Doc 4444.", cite: "PANS-ATM Doc 4444 12.3.1.14 (UNABLE RVSM DUE EQUIPMENT)" },
  { id: "q_laof_2_235", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es la fraseología correcta en inglés que el piloto requiere hacer para indicar que efectúa un descenso de emergencia?", options: ["Descending rapidly to flight level/altitude…", "Emergency descent.", "Going down to flight level/altitude…"], correctIndex: 1, explanation: "La fraseología de emergencia del Doc 4444 (12.3.1.2) prevé 'EMERGENCY DESCENT (intentions)' para advertir a las demás aeronaves que se ejecuta un descenso de emergencia. Las otras dos redacciones son coloquiales y no normalizadas.", cite: "PANS-ATM Doc 4444 12.3.1.2 (EMERGENCY DESCENT)" },
  { id: "q_laof_2_236", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la altitud 14,500 pies?", options: ["Catorce más quinientos.", "Uno cuatro mil quinientos pies.", "Catorce punto cinco."], correctIndex: 1, explanation: "El Anexo 10 (5.2.1.4.1.5) manda transmitir las altitudes que contienen miles y centenas enteros pronunciando cada dígito del número de miles seguido de MIL y las centenas seguidas de CIEN(TOS): uno cuatro mil quinientos (one four thousand five hundred). Los formatos 'punto' o 'más' no existen en radiotelefonía aeronáutica.", cite: "Annex 10 Vol II 5.2.1.4.1.5 (transmisión de altitudes; ej. 3 400 = 'three thousand four hundred')" },
  { id: "q_laof_2_237", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la altitud 17,400 pies?", options: ["Diecisiete punto cuatro.", "Uno siete mil cuatrocientos pies.", "Diecisiete más cuatrocientos."], correctIndex: 1, explanation: "El Anexo 10 (5.2.1.4.1.5) manda transmitir las altitudes que contienen miles y centenas enteros pronunciando cada dígito del número de miles seguido de MIL y las centenas seguidas de CIEN(TOS): uno siete mil cuatrocientos (one seven thousand four hundred). Los formatos 'punto' o 'más' no existen en radiotelefonía aeronáutica.", cite: "Annex 10 Vol II 5.2.1.4.1.5 (transmisión de altitudes; ej. 3 400 = 'three thousand four hundred')" },
  { id: "q_laof_2_238", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la altitud 13,200 pies?", options: ["Trece punto dos.", "Uno tres mil doscientos pies.", "Trece más doscientos."], correctIndex: 1, explanation: "El Anexo 10 (5.2.1.4.1.5) manda transmitir las altitudes que contienen miles y centenas enteros pronunciando cada dígito del número de miles seguido de MIL y las centenas seguidas de CIEN(TOS): uno tres mil doscientos (one three thousand two hundred). Los formatos 'punto' o 'más' no existen en radiotelefonía aeronáutica.", cite: "Annex 10 Vol II 5.2.1.4.1.5 (transmisión de altitudes; ej. 3 400 = 'three thousand four hundred')" },
  { id: "q_laof_2_239", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la altitud 18,100 pies?", options: ["Uno ocho mil cien pies.", "Dieciocho más cien.", "Dieciocho punto uno."], correctIndex: 0, explanation: "El Anexo 10 (5.2.1.4.1.5) manda transmitir las altitudes que contienen miles y centenas enteros pronunciando cada dígito del número de miles seguido de MIL y las centenas seguidas de CIEN(TOS): uno ocho mil cien (one eight thousand one hundred). Los formatos 'punto' o 'más' no existen en radiotelefonía aeronáutica.", cite: "Annex 10 Vol II 5.2.1.4.1.5 (transmisión de altitudes; ej. 3 400 = 'three thousand four hundred')" },
  { id: "q_laof_2_240", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la altitud 16,900 pies?", options: ["Alcanzando uno siete mil.", "Uno seis mil novecientos pies.", "Dieciséis más novecientos."], correctIndex: 1, explanation: "El Anexo 10 (5.2.1.4.1.5) manda transmitir las altitudes que contienen miles y centenas enteros pronunciando cada dígito del número de miles seguido de MIL y las centenas seguidas de CIEN(TOS): uno seis mil novecientos (one six thousand nine hundred). Los formatos 'punto' o 'más' no existen en radiotelefonía aeronáutica.", cite: "Annex 10 Vol II 5.2.1.4.1.5 (transmisión de altitudes; ej. 3 400 = 'three thousand four hundred')" },
  { id: "q_laof_2_241", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la velocidad 180KIAS?", options: ["Ciento ochenta en la velocidad.", "Ciento ochenta nudos.", "Uno ocho cero nudos indicados."], correctIndex: 2, explanation: "Las velocidades se transmiten pronunciando cada dígito por separado (Anexo 10, 5.2.1.4.1.1; ej. 'wind two zero zero degrees seven zero knots'): uno ocho cero nudos. Decir el número corrido ('ciento...') o añadir 'en la velocidad' no es fraseología estándar.", cite: "Annex 10 Vol II 5.2.1.4.1.1 (todos los números, dígito por dígito)" },
  { id: "q_laof_2_242", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la velocidad 170KIAS?", options: ["Ciento setenta.", "Ciento setenta en la velocidad.", "Uno siete cero nudos indicados."], correctIndex: 2, explanation: "Las velocidades se transmiten pronunciando cada dígito por separado (Anexo 10, 5.2.1.4.1.1; ej. 'wind two zero zero degrees seven zero knots'): uno siete cero nudos. Decir el número corrido ('ciento...') o añadir 'en la velocidad' no es fraseología estándar.", cite: "Annex 10 Vol II 5.2.1.4.1.1 (todos los números, dígito por dígito)" },
  { id: "q_laof_2_243", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la velocidad 160KIAS?", options: ["Ciento sesenta en la velocidad.", "Ciento sesenta.", "Uno seis cero nudos indicados."], correctIndex: 2, explanation: "Las velocidades se transmiten pronunciando cada dígito por separado (Anexo 10, 5.2.1.4.1.1; ej. 'wind two zero zero degrees seven zero knots'): uno seis cero nudos. Decir el número corrido ('ciento...') o añadir 'en la velocidad' no es fraseología estándar.", cite: "Annex 10 Vol II 5.2.1.4.1.1 (todos los números, dígito por dígito)" },
  { id: "q_laof_2_244", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la velocidad 150KIAS?", options: ["Uno cinco cero nudos indicados.", "Ciento cincuenta en la velocidad.", "Ciento cincuenta."], correctIndex: 0, explanation: "Las velocidades se transmiten pronunciando cada dígito por separado (Anexo 10, 5.2.1.4.1.1; ej. 'wind two zero zero degrees seven zero knots'): uno cinco cero nudos. Decir el número corrido ('ciento...') o añadir 'en la velocidad' no es fraseología estándar.", cite: "Annex 10 Vol II 5.2.1.4.1.1 (todos los números, dígito por dígito)" },
  { id: "q_laof_2_245", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la velocidad 140KIAS?", options: ["Ciento cuarenta.", "Uno cuatro cero nudos indicados.", "Ciento cuarenta en la velocidad."], correctIndex: 1, explanation: "Las velocidades se transmiten pronunciando cada dígito por separado (Anexo 10, 5.2.1.4.1.1; ej. 'wind two zero zero degrees seven zero knots'): uno cuatro cero nudos. Decir el número corrido ('ciento...') o añadir 'en la velocidad' no es fraseología estándar.", cite: "Annex 10 Vol II 5.2.1.4.1.1 (todos los números, dígito por dígito)" },
  { id: "q_laof_2_246", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas el rumbo 345º?", options: ["Rumbo tres cuarenta y cinco.", "Rumbo tres cuatro cinco.", "Rumbo trescientos cuarenta y cinco."], correctIndex: 1, explanation: "Los rumbos se transmiten dígito por dígito conforme al Anexo 10 (5.2.1.4.1.1, ej. 'heading one zero zero'): rumbo tres cuatro cinco. Las formas corridas ('trescientos cuarenta y cinco') no son fraseología normalizada.", cite: "Annex 10 Vol II 5.2.1.4.1.1 (headings: cada dígito por separado)" },
  { id: "q_laof_3_247", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas el rumbo 255º?", options: ["Rumbo doscientos cincuenta y cinco.", "Rumbo dos cinco cinco.", "Rumbo dos cincuenta y cinco."], correctIndex: 1, explanation: "La fraseología OACI exige transmitir los rumbos con tres cifras pronunciando cada dígito por separado: 255º se enuncia 'rumbo dos cinco cinco'. Las formas coloquiales agrupadas no están permitidas.", cite: "Annex 10 Vol. II, 5.2.1.4.1 (transmisión de números)" },
  { id: "q_laof_3_248", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas el rumbo 180º?", options: ["Rumbo sur.", "Rumbo uno ocho cero.", "Rumbo ciento ochenta."], correctIndex: 1, explanation: "Los rumbos se transmiten con tres dígitos pronunciados por separado: 180º = 'rumbo uno ocho cero'. No se emplean puntos cardinales ('rumbo sur') en la fraseología normalizada.", cite: "Annex 10 Vol. II, 5.2.1.4.1" },
  { id: "q_laof_3_249", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas el rumbo 360º?", options: ["Rumbo norte.", "Rumbo tres seis cero.", "Rumbo tres sesenta."], correctIndex: 1, explanation: "El norte se expresa como rumbo 360 con cada dígito por separado: 'rumbo tres seis cero'. 'Rumbo norte' no es fraseología normalizada.", cite: "Annex 10 Vol. II, 5.2.1.4.1" },
  { id: "q_laof_3_250", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas el rumbo 270º?", options: ["Rumbo Whisky.", "Rumbo doscientos setenta.", "Rumbo dos siete cero."], correctIndex: 2, explanation: "270º se transmite dígito por dígito: 'rumbo dos siete cero'. Referencias a letras del alfabeto fonético o números agrupados son incorrectas.", cite: "Annex 10 Vol. II, 5.2.1.4.1" },
  { id: "q_laof_3_251", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la frecuencia 119.55 MHz?", options: ["Uno uno nueve decimal cinco cinco.", "Uno uno nueve punto cinco cinco.", "Ciento diecinueve cincuenta y cinco."], correctIndex: 0, explanation: "En frecuencias VHF cada dígito se pronuncia por separado y la coma decimal se enuncia 'decimal', nunca 'punto'. Con separación de canales de 25 kHz se transmiten los primeros cinco dígitos: 119.550 = 'uno uno nueve decimal cinco cinco'.", cite: "Annex 10 Vol. II, 5.2.1.4.1.2 y 5.2.1.4.3.4" },
  { id: "q_laof_3_252", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la frecuencia 120.50 MHz?", options: ["Ciento veinte cincuenta.", "Uno dos cero punto cinco.", "Uno dos cero decimal cinco."], correctIndex: 2, explanation: "Cuando el quinto y sexto dígitos del designador son ceros, solo se transmiten los primeros cuatro dígitos: 120.500 = 'uno dos cero decimal cinco'. Se usa la palabra 'decimal', no 'punto'.", cite: "Annex 10 Vol. II, 5.2.1.4.3.4" },
  { id: "q_laof_3_253", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la frecuencia 121.50 MHz?", options: ["Ciento veintiuno cincuenta.", "Uno dos uno punto cinco.", "Uno dos uno decimal cinco."], correctIndex: 2, explanation: "121.500: quinto y sexto dígitos en cero, se transmiten los primeros cuatro dígitos con la palabra 'decimal': 'uno dos uno decimal cinco'.", cite: "Annex 10 Vol. II, 5.2.1.4.3.4" },
  { id: "q_laof_3_254", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la frecuencia 123.45 MHz?", options: ["Uno dos tres decimal cuatro cinco.", "Uno dos tres punto cuatro cinco.", "Ciento veintitrés cuarenta y cinco."], correctIndex: 0, explanation: "123.450: el quinto dígito no es cero, por lo que se transmiten los primeros cinco dígitos: 'uno dos tres decimal cuatro cinco'. 'Punto' no es la palabra normalizada.", cite: "Annex 10 Vol. II, 5.2.1.4.3.4" },
  { id: "q_laof_3_255", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe enunciarse en las transmisiones radiotelefónicas aeronáuticas la frecuencia 129.60 MHz?", options: ["Uno dos nueve punto seis.", "Uno dos nueve decimal seis.", "Ciento veintinueve seis."], correctIndex: 1, explanation: "129.600: quinto y sexto dígitos en cero, se transmiten los primeros cuatro dígitos: 'uno dos nueve decimal seis', usando 'decimal' y no 'punto'.", cite: "Annex 10 Vol. II, 5.2.1.4.3.4" },
  { id: "q_laof_3_256", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál de las siguientes opciones ejemplifica una correcta transmisión radiotelefónica aeronáutica?", options: ["Centro Monterrey, Costera dos cuatro cinco, nivel de vuelo dos cuatro cero.", "Centro Monterrey, Costera dos cuarenta y cinco, dos cuatro cero nivel.", "Monterrey buenas tardes, el Costera dos cuatro cinco, nivel dos cuatro cero."], correctIndex: 0, explanation: "La estructura correcta es: distintivo de la estación llamada ('Centro ...'), distintivo de llamada completo de la aeronave con cada dígito por separado y el nivel con la expresión 'nivel de vuelo' seguida de sus dígitos. Saludos, artículos y números agrupados no corresponden a la fraseología normalizada.", cite: "Annex 10 Vol. II, 5.2.1.7 y 5.2.1.4.1" },
  { id: "q_laof_3_257", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál de las siguientes opciones ejemplifica una correcta transmisión radiotelefónica aeronáutica?", options: ["Centro Monterrey, Costera dos cuatro cinco ocho, nivel de vuelo tres cuatro cero.", "Monterrey buenas tardes, el Costera dos cuatro cinco ocho, nivel tres cuatro cero.", "Centro Monterrey, Costera dos cuatro cincuenta y ocho, tres cuatro cero nivel."], correctIndex: 0, explanation: "La estructura correcta es: distintivo de la estación llamada ('Centro ...'), distintivo de llamada completo de la aeronave con cada dígito por separado y el nivel con la expresión 'nivel de vuelo' seguida de sus dígitos. Saludos, artículos y números agrupados no corresponden a la fraseología normalizada.", cite: "Annex 10 Vol. II, 5.2.1.7 y 5.2.1.4.1" },
  { id: "q_laof_3_258", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál de las siguientes opciones ejemplifica una correcta transmisión radiotelefónica aeronáutica?", options: ["Centro México, Costera dos cinco dos, nivel de vuelo dos cuatro cero.", "México buenas tardes, el Costera dos cinco dos, nivel dos cuatro cero.", "Centro México, Costera dos cinco dos, dos cuatro cero nivel."], correctIndex: 0, explanation: "La estructura correcta es: distintivo de la estación llamada ('Centro ...'), distintivo de llamada completo de la aeronave con cada dígito por separado y el nivel con la expresión 'nivel de vuelo' seguida de sus dígitos. Saludos, artículos y números agrupados no corresponden a la fraseología normalizada.", cite: "Annex 10 Vol. II, 5.2.1.7 y 5.2.1.4.1" },
  { id: "q_laof_3_259", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál de las siguientes opciones ejemplifica una correcta transmisión radiotelefónica aeronáutica?", options: ["Mérida buenas tardes, el Costera dos uno uno, nivel dos cuatro cero.", "Centro Mérida, Costera dos once, dos cuatro cero nivel.", "Centro Mérida, Costera dos uno uno, nivel de vuelo dos cuatro cero."], correctIndex: 2, explanation: "La estructura correcta es: distintivo de la estación llamada ('Centro ...'), distintivo de llamada completo de la aeronave con cada dígito por separado y el nivel con la expresión 'nivel de vuelo' seguida de sus dígitos. Saludos, artículos y números agrupados no corresponden a la fraseología normalizada.", cite: "Annex 10 Vol. II, 5.2.1.7 y 5.2.1.4.1" },
  { id: "q_laof_3_260", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál de las siguientes opciones ejemplifica una correcta transmisión radiotelefónica aeronáutica?", options: ["Centro Mazatlán, Costera triple dos, dos cuatro cero nivel.", "Centro Mazatlán, Costera dos dos dos, nivel de vuelo dos cuatro cero.", "Mazatlán buenas tardes, el Costera dos dos dos, nivel dos cuatro cero."], correctIndex: 1, explanation: "La estructura correcta es: distintivo de la estación llamada ('Centro ...'), distintivo de llamada completo de la aeronave con cada dígito por separado y el nivel con la expresión 'nivel de vuelo' seguida de sus dígitos. Saludos, artículos y números agrupados no corresponden a la fraseología normalizada.", cite: "Annex 10 Vol. II, 5.2.1.7 y 5.2.1.4.1" },
  { id: "q_laof_3_261", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es el propósito principal de la fraseología normalizada de la OACI?", options: ["Reducir la posibilidad de malentendidos entre pilotos y controladores.", "Agilizar únicamente las transmisiones militares.", "Permitir que cada Estado utilice expresiones locales."], correctIndex: 0, explanation: "La fraseología normalizada existe para lograr comunicaciones claras, concisas e inequívocas entre pilotos y controladores, reduciendo malentendidos que históricamente han causado accidentes (p. ej. Tenerife 1977). No es exclusiva militar ni admite regionalismos.", cite: "Annex 10 Vol. II, Cap. 5; Doc 9432 (Manual de radiotelefonía)" },
  { id: "q_laof_3_262", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué palabra debe utilizarse para indicar que un mensaje requiere máxima prioridad por peligro grave e inminente?", options: ["Pan-pan.", "Alert.", "Mayday."], correctIndex: 2, explanation: "MAYDAY es la señal de socorro (distress): condición de peligro grave e inminente que requiere auxilio inmediato y otorga máxima prioridad; se transmite preferiblemente tres veces.", cite: "Annex 10 Vol. II, 5.3.1 (procedimientos de socorro)" },
  { id: "q_laof_3_263", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es la palabra radiotelefónica utilizada para indicar urgencia cuando no existe un peligro inmediato para la aeronave?", options: ["Pan-pan.", "Mayday.", "Emergency."], correctIndex: 0, explanation: "PAN PAN es la señal de urgencia: condición que concierne a la seguridad de la aeronave u ocupantes pero que no requiere auxilio inmediato ni implica peligro inminente.", cite: "Annex 10 Vol. II, 5.3.2 (procedimientos de urgencia)" },
  { id: "q_laof_3_264", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo debe transmitirse normalmente un número de nivel de vuelo?", options: ["Pronunciando cada dígito por separado.", "Únicamente con centenas.", "Como un número entero antecediendo la palabra “altitud”"], correctIndex: 0, explanation: "Los niveles de vuelo se transmiten pronunciando cada dígito por separado: FL240 = 'nivel de vuelo dos cuatro cero'. (La excepción de centenas enteras 'flight level one hundred' no altera la regla general.)", cite: "Annex 10 Vol. II, 5.2.1.4.1.1" },
  { id: "q_laof_3_265", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué estación debe finalizar una comunicación cuando se requiere confirmar la recepción de un mensaje?", options: ["La estación con mayor potencia de transmisión.", "La estación que recibe el mensaje.", "La estación que originó el mensaje."], correctIndex: 1, explanation: "El Anexo 10 establece en 'End of conversation' que la conversación radiotelefónica debe ser terminada por la estación receptora transmitiendo su propio distintivo de llamada.", cite: "Annex 10 Vol. II, 5.2.1.9.3" },
  { id: "q_laof_3_266", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué expresión se utiliza para indicar que un mensaje ha sido recibido y comprendido correctamente?", options: ["Affirm.", "Roger.", "Wilco."], correctIndex: 1, explanation: "ROGER significa 'he recibido íntegra su última transmisión' y es el acuse de recibo estándar. AFFIRM se reserva para responder 'sí' a una pregunta y WILCO añade el compromiso de cumplir la instrucción.", cite: "Annex 10 Vol. II, 5.2.1.8 (palabras y frases normalizadas)" },
  { id: "q_laof_3_267", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué significa la expresión \"wilco\"?", options: ["No puedo cumplir la autorización (unable to comply).", "He recibido el mensaje, lo comprendo y cumpliré la instrucción.", "Repita el mensaje."], correctIndex: 1, explanation: "WILCO es abreviatura de 'will comply': 'comprendo su mensaje y lo cumpliré'. Implica recepción, comprensión y compromiso de cumplimiento.", cite: "Annex 10 Vol. II, 5.2.1.8" },
  { id: "q_laof_3_268", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué palabra o frase debe emplearse para solicitar que una transmisión sea repetida?", options: ["Say again.", "Stand by.", "Acknowledge again."], correctIndex: 0, explanation: "SAY AGAIN es la frase normalizada para pedir repetición total o parcial de la última transmisión (SAY AGAIN ALL BEFORE/AFTER...).", cite: "Annex 10 Vol. II, 5.2.1.8 y 5.2.1.9.4.5" },
  { id: "q_laof_3_269", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué palabra debe utilizarse para responder afirmativamente a una pregunta?", options: ["Roger.", "Copy that.", "Affirm."], correctIndex: 2, explanation: "AFFIRM significa 'sí' y es la respuesta afirmativa normalizada a una pregunta. ROGER solo acusa recibo y no debe usarse para responder preguntas de sí/no.", cite: "Annex 10 Vol. II, 5.2.1.8" },
  { id: "q_laof_3_270", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué palabra debe utilizarse para responder negativamente a una pregunta?", options: ["Negative.", "Cancel.", "Unable."], correctIndex: 0, explanation: "NEGATIVE significa 'no', 'permiso no concedido' o 'eso no es correcto'; es la respuesta negativa normalizada.", cite: "Annex 10 Vol. II, 5.2.1.8" },
  { id: "q_laof_3_271", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué expresión debe utilizar un piloto cuando no puede cumplir una autorización del CTA?", options: ["Stand by one.", "Negative.", "Unable."], correctIndex: 2, explanation: "UNABLE significa 'no puedo cumplir con su solicitud, instrucción o autorización' y es la expresión normalizada cuando el piloto no puede cumplir lo autorizado por el CTA.", cite: "Annex 10 Vol. II, 5.2.1.8" },
  { id: "q_laof_3_272", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cómo deben transmitirse normalmente las horas en radiotelefonía aeronáutica?", options: ["Utilizando cuatro cifras que representen horas y minutos.", "Únicamente indicando los minutos (si se refiere a la hora en la que actualmente se encuentre).", "Expresándolas en formato de doce horas con AM o PM."], correctIndex: 1, explanation: "Al transmitir la hora normalmente solo se requieren los minutos de la hora, pronunciando cada dígito por separado; la hora completa (cuatro cifras) se incluye únicamente cuando pueda haber confusión.", cite: "Annex 10 Vol. II, 5.2.1.4.1.8" },
  { id: "q_laof_3_273", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué palabra se utiliza para indicar que debe esperarse una nueva transmisión?", options: ["Hold.", "Stand by.", "Wait."], correctIndex: 1, explanation: "STANDBY significa 'espere, yo lo llamaré': indica que debe esperarse una nueva transmisión de la estación.", cite: "Annex 10 Vol. II, 5.2.1.8" },
  { id: "q_laof_3_274", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué expresión debe emplearse cuando se corrige un error cometido durante una transmisión?", options: ["Correction.", "Cancel.", "Revision."], correctIndex: 0, explanation: "Cuando se comete un error en la transmisión debe decirse 'CORRECTION', repetirse el último grupo o frase correcta y transmitirse la versión correcta.", cite: "Annex 10 Vol. II, 5.2.1.9.4.1" },
  { id: "q_laof_3_275", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué elemento debe incluir normalmente una autorización CTA?", options: ["El distintivo de llamada de la aeronave.", "El nombre del piloto al mando.", "La matrícula completa de la aeronave y del controlador."], correctIndex: 0, explanation: "Para evitar confusiones, al emitir y colacionar autorizaciones ATC, controladores y pilotos deben añadir siempre el distintivo de llamada de la aeronave a la que aplica la autorización.", cite: "Annex 10 Vol. II, 5.2.1.7.3.3.3" },
  { id: "q_laof_3_276", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué expresión debe utilizarse para cancelar una autorización previamente emitida?", options: ["Cancel.", "Negative clearance.", "Disregard."], correctIndex: 0, explanation: "CANCEL significa 'anule la autorización transmitida previamente' y es la expresión normalizada para cancelar una autorización emitida.", cite: "Annex 10 Vol. II, 5.2.1.8" },
  { id: "q_laof_3_277", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué debe hacer una estación si recibe una transmisión dudosa o incompleta?", options: ["Solicitar la repetición del mensaje o de la parte dudosa.", "Ignorar el mensaje y continuar la operación.", "Asumir el significado por contexto."], correctIndex: 0, explanation: "Si el operador receptor tiene dudas sobre la corrección del mensaje recibido, debe solicitar su repetición total o parcial; nunca asumir el significado por contexto.", cite: "Annex 10 Vol. II, 5.2.1.9.4.4" },
  { id: "q_laof_3_278", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Cuál es el objetivo principal de una colación por parte del piloto?", options: ["Confirmar que la autorización crítica fue recibida correctamente.", "Reducir el tiempo de ocupación de la frecuencia.", "Sustituir la necesidad de escuchar al controlador."], correctIndex: 0, explanation: "La colación (readback) consiste en repetir el mensaje o parte pertinente a la estación transmisora para obtener confirmación de la recepción correcta; es obligatoria en autorizaciones e instrucciones críticas.", cite: "Annex 10 Vol. II, definición de 'Readback' y 5.2.1.9.2.2" },
  { id: "q_laof_3_279", fuente: LA_OFICIAL_FUENTE, materia: "comunicaciones", tema: "COMS", text: "¿Qué característica debe tener la transmisión radiotelefónica normal?", options: ["Ser rápida, aunque algunas palabras sean difíciles de entender para eficiencia de la frecuencia.", "Ser clara, concisa y realizada a una velocidad adecuada para su comprensión.", "Ser lo más extensa posible para evitar dudas."], correctIndex: 1, explanation: "La técnica de transmisión exige enunciación clara, mensajes concisos y un ritmo de habla constante y adecuado que permita comprender y anotar el mensaje; la rapidez nunca debe sacrificar la claridad.", cite: "Annex 10 Vol. II, 5.2.1.5 (técnica de transmisión); Doc 9432" },
  { id: "q_laof_3_280", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "What is the main purpose of an Airworthiness Certificate?", options: ["Certify aircraft is safe for operation.", "Approve airport use.", "Approve flight plan.", "Authorize pilot to fly."], correctIndex: 0, explanation: "The airworthiness certificate attests that the aircraft conforms to its approved type design and is in condition for safe operation. It does not approve airports or flight plans, nor authorize pilots.", cite: "PHAK Cap. 9 (Flight Manuals and Other Documents); 14 CFR 21.183" },
  { id: "q_laof_3_281", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Who has final authority regarding aircraft operation?", options: ["Pilot in Command.", "Maintenance Control.", "First Officer.", "Dispatcher."], correctIndex: 0, explanation: "The pilot in command is directly responsible for, and is the final authority as to, the operation of the aircraft. Dispatcher and maintenance share responsibilities but the final operational authority rests with the PIC.", cite: "14 CFR 91.3(a); principio equivalente en la legislación aeronáutica mexicana (piloto al mando)" },
  { id: "q_laof_3_282", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "What is the legal alcohol limitation before acting as crew member?", options: ["4 hours.", "8 hours.", "6 hours.", "12 hours."], correctIndex: 1, explanation: "The '8 hours bottle-to-throttle' rule: no person may act as a crewmember within 8 hours after consuming alcohol, while under its influence, or with 0.04% or more blood alcohol.", cite: "14 CFR 91.17" },
  { id: "q_laof_3_283", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "A pilot may deviate from regulations when:", options: ["Emergency requires immediate action.", "ATC suggests it.", "Company requests it.", "Weather is good."], correctIndex: 0, explanation: "In an in-flight emergency requiring immediate action, the PIC may deviate from any rule to the extent required to meet that emergency. Ni la sugerencia de ATC, ni la compañía, ni el buen tiempo autorizan desviarse de la reglamentación.", cite: "14 CFR 91.3(b)" },
  { id: "q_laof_3_284", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "A NOTAM provides information about:", options: ["Aircraft ownership.", "Passenger lists.", "Flight hazards and operational changes.", "Crew schedules."], correctIndex: 2, explanation: "A NOTAM disseminates time-critical aeronautical information on hazards and operational changes (runway/taxiway closures, unserviceable navaids, obstacles) not known far enough in advance for other publications.", cite: "PHAK Cap. 1; AIM 5-1-3; Anexo 15 OACI" },
  { id: "q_laof_3_285", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Sterile cockpit applies during:", options: ["Cruise only.", "Night flights only.", "Emergencies only.", "Taxi, takeoff, landing, below 10,000 ft."], correctIndex: 3, explanation: "The sterile cockpit rule prohibits nonessential duties and conversation during critical phases of flight: taxi, takeoff, landing, and all flight operations below 10,000 ft except cruise flight.", cite: "14 CFR 121.542 (Flight crewmember duties)" },
  { id: "q_laof_3_286", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Minimum fuel declaration means:", options: ["Aircraft emergency exists.", "Immediate landing required.", "No delay can be accepted safely.", "Engine failure occurred."], correctIndex: 2, explanation: "'Minimum fuel' is an advisory, not an emergency: it indicates that upon reaching destination the flight can accept little or no delay. Immediate landing is not required; if further delay would compromise reserves, the crew escalates to MAYDAY FUEL.", cite: "AIM 5-5-15 / Pilot/Controller Glossary; ICAO Doc 4444 (fuel phraseology)" },
  { id: "q_laof_3_287", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Which document contains route, altitude, fuel and alternate data?", options: ["Journey log only.", "Flight release/dispatch release.", "Maintenance release.", "Airworthiness certificate."], correctIndex: 1, explanation: "The dispatch/flight release contains the operational plan of the flight: route, minimum altitudes, fuel required, destination and alternate airports, and weather information.", cite: "14 CFR 121.687 (contents of dispatch release)" },
  { id: "q_laof_3_288", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "IFR fuel must include: Destination + alternate + reserve.", options: ["Destination only.", "Alternate only.", "Destination + alternate + reserve.", "Taxi fuel only."], correctIndex: 2, explanation: "IFR fuel requirements: fuel to fly to the destination, then to the alternate (when required), plus final reserve (45 min FAA domestic; en 121 de bandera se añade 10% de contingencia). Nota: en el banco el propio enunciado incluye la respuesta, error de formato del documento fuente.", cite: "14 CFR 91.167 / 121.639" },
  { id: "q_laof_3_289", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Who determines if aircraft is safe before departure?", options: ["ATC.", "PIC.", "Cabin crew.", "Ground agent."], correctIndex: 1, explanation: "The pilot in command is responsible for determining whether the aircraft is in condition for safe flight before departure (preflight inspection, airworthiness review, MEL items).", cite: "14 CFR 91.7(b); PHAK Cap. 2" },
  { id: "q_laof_3_290", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "Lift is generated primarily by:", options: ["Airflow over wing surfaces.", "Engine thrust.", "Landing gear drag.", "Cabin pressure."], correctIndex: 0, explanation: "Lift results from the pressure differential created by airflow over the wing surfaces (Bernoulli/Newton): accelerated flow over the upper camber lowers pressure relative to the lower surface. Thrust contributes but is not the primary lift generator.", cite: "PHAK Cap. 4-5 (Principles of Flight / Aerodynamics of Flight)" },
  { id: "q_laof_3_291", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "A stall occurs when:", options: ["Engine stops.", "Speed reaches zero.", "Critical angle of attack exceeded.", "Gear is extended."], correctIndex: 2, explanation: "A stall occurs when the critical angle of attack is exceeded and airflow separates from the upper wing surface. It can occur at any airspeed, attitude, or power setting.", cite: "PHAK Cap. 5" },
  { id: "q_laof_3_292", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "Induced drag is greatest:", options: ["High speed.", "Cruise flight.", "Low speed/high angle of attack.", "Descent only."], correctIndex: 2, explanation: "Induced drag is a byproduct of lift generation and is greatest at low airspeed and high angle of attack; it varies inversely with the square of airspeed.", cite: "PHAK Cap. 5" },
  { id: "q_laof_3_293", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "Parasite drag increases with:", options: ["Lower speed.", "Lower altitude.", "Higher speed.", "Lower weight."], correctIndex: 2, explanation: "Parasite drag (form, skin friction, interference) increases with the square of airspeed: doubling speed quadruples parasite drag.", cite: "PHAK Cap. 5" },
  { id: "q_laof_3_294", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "Load factor increases in a turn because:", options: ["Weight decreases.", "Drag disappears.", "Thrust increases automatically.", "More lift is required."], correctIndex: 3, explanation: "In a level turn, lift is inclined and its vertical component must still support weight, so total lift must increase; that additional lift raises the load factor (60° bank = 2 g).", cite: "PHAK Cap. 5 (Load Factors in Turns)" },
  { id: "q_laof_3_295", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "Ground effect reduces:", options: ["Lift.", "Parasite drag.", "Weight.", "Induced drag."], correctIndex: 3, explanation: "Within about one wingspan of the surface, ground effect interferes with wingtip vortices and downwash, reducing induced drag — the airplane 'floats' on landing and may lift off prematurely on takeoff.", cite: "PHAK Cap. 5 (Ground Effect, 5-11)" },
  { id: "q_laof_3_296", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "Winglets help reduce:", options: ["Induced drag.", "Parasite drag.", "Weight.", "Fuel pressure loss."], correctIndex: 0, explanation: "Winglets weaken the wingtip vortex, reducing induced drag and improving cruise efficiency and range.", cite: "PHAK Cap. 5" },
  { id: "q_laof_3_297", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "Flaps primarily:", options: ["Reduce lift.", "Increase lift and drag.", "Eliminate drag.", "Increase cruise speed."], correctIndex: 1, explanation: "Flaps increase wing camber (and in Fowler types, area), increasing both lift and drag: they allow slower approach speeds and steeper descent angles without increasing airspeed.", cite: "PHAK Cap. 6 (Flight Controls)" },
  { id: "q_laof_3_298", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "Forward CG generally makes aircraft:", options: ["Less stable.", "Impossible to stall.", "More stable.", "Faster."], correctIndex: 2, explanation: "A forward CG increases longitudinal static stability (greater tail-down force arm), though it also increases stall speed and trim drag. Excessively forward CG can limit flare authority.", cite: "PHAK Cap. 10 (Weight and Balance) y Cap. 5 (estabilidad)" },
  { id: "q_laof_3_299", fuente: LA_OFICIAL_FUENTE, materia: "aerodinamica", tema: "AERO", text: "Aft CG makes aircraft:", options: ["More stable.", "Easier to control in recovery.", "Less stable.", "Heavier."], correctIndex: 2, explanation: "An aft CG reduces longitudinal stability and makes stall/spin recovery more difficult; beyond the aft limit the aircraft can become dangerously unstable.", cite: "PHAK Cap. 10" },
  { id: "q_laof_3_300", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "METAR is:", options: ["Current weather observation.", "Forecast.", "Turbulence alert.", "Winds aloft report."], correctIndex: 0, explanation: "METAR is the aviation routine weather report: an observation of current conditions at an aerodrome (wind, visibility, weather, clouds, temperature/dew point, altimeter).", cite: "PHAK Cap. 13 (Aviation Weather Services)" },
  { id: "q_laof_3_301", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "TAF gives:", options: ["Terminal forecast.", "Current weather.", "Pressure altitude.", "Wind shear only."], correctIndex: 0, explanation: "TAF (Terminal Aerodrome Forecast) is a forecast for the area within 5 SM of an airport, typically valid 24-30 hours.", cite: "PHAK Cap. 13" },
  { id: "q_laof_3_302", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Thunderstorms require:", options: ["Cold air only.", "Calm winds only.", "Fog and snow.", "Moisture, instability, lift."], correctIndex: 3, explanation: "Thunderstorm formation requires three ingredients: sufficient water vapor (moisture), an unstable lapse rate, and an initial lifting action (frontal, orographic, or thermal).", cite: "PHAK Cap. 12 (Weather Theory)" },
  { id: "q_laof_3_303", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Cumulonimbus clouds indicate:", options: ["Calm weather.", "Severe turbulence potential.", "Stable air only.", "Fog formation only."], correctIndex: 1, explanation: "The cumulonimbus is the thunderstorm cloud: it implies severe-to-extreme turbulence, hail, icing, lightning, wind shear and microbursts, and must be avoided by a wide margin.", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_304", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Wind shear is most dangerous during:", options: ["Cruise.", "Taxi.", "Takeoff and landing.", "Shutdown."], correctIndex: 2, explanation: "Wind shear is most dangerous at low altitude during takeoff and approach/landing, where there is little altitude and energy margin to recover from sudden airspeed/performance losses (microbursts).", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_305", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Rime ice forms from:", options: ["Large droplets.", "Fuel leaks.", "Small supercooled droplets.", "Dry air only."], correctIndex: 2, explanation: "Rime ice forms when small supercooled droplets freeze instantly on impact, trapping air: rough, milky, opaque and brittle ice.", cite: "PHAK Cap. 12 y glosario ('Rime ice')" },
  { id: "q_laof_3_306", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Clear ice forms from:", options: ["Dry snow.", "Fog only.", "Large supercooled droplets.", "Static discharge."], correctIndex: 2, explanation: "Clear ice forms from large supercooled droplets that freeze slowly and flow back over the surface: glossy, dense, heavy, hard to remove — the most dangerous structural ice.", cite: "PHAK Cap. 12 y glosario ('Clear ice')" },
  { id: "q_laof_3_307", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Fog forms easily when:", options: ["Winds strong.", "Pressure low only.", "Air very dry.", "Temp and dew point close together."], correctIndex: 3, explanation: "Fog forms when temperature and dew point converge (small spread, typically within about 2.5 °C) and the air near the surface saturates.", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_308", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Density altitude increases when temperature:", options: ["Drops.", "Equals dew point.", "Reaches freezing.", "Rises."], correctIndex: 3, explanation: "Density altitude increases with rising temperature (less dense air): the aircraft performs as if at a higher altitude, degrading takeoff, climb, and engine performance.", cite: "PHAK Cap. 11 (Aircraft Performance)" },
  { id: "q_laof_3_309", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Microbursts create:", options: ["Sudden dangerous downdrafts.", "Gentle winds.", "Clear skies.", "Stable air only."], correctIndex: 0, explanation: "A microburst is an intense, localized downdraft (up to ~6,000 ft/min) that produces devastating headwind-to-tailwind shifts on approach or departure; peak intensity lasts only minutes.", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_310", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "A temperature inversion results in:", options: ["Strong vertical mixing.", "Increased turbulence.", "Rapid cloud dissipation.", "Stable air and reduced visibility."], correctIndex: 3, explanation: "A temperature inversion (temperature increasing with height) traps stable, stagnant air: smooth flight but poor visibility from haze, smoke, or fog held near the surface.", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_311", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "An AIRMET is issued for:", options: ["Severe hazards only.", "Only thunderstorms.", "Only icing.", "Moderate weather conditions affecting smaller aircraft."], correctIndex: 3, explanation: "AIRMETs cover moderate conditions (icing, turbulence, IFR ceilings/visibility, sustained surface winds) significant primarily to smaller/light aircraft.", cite: "PHAK Cap. 13" },
  { id: "q_laof_3_312", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "A SIGMET is issued for:", options: ["Severe weather hazards.", "Light turbulence.", "Clear skies.", "Fog only."], correctIndex: 0, explanation: "SIGMETs warn of severe weather significant to all aircraft: severe icing, severe or extreme turbulence, dust/sandstorms, volcanic ash (and convective SIGMETs for thunderstorm activity).", cite: "PHAK Cap. 13" },
  { id: "q_laof_3_313", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Mountain waves are associated with:", options: ["Calm winds.", "Only thunderstorms.", "Strong winds over terrain and stable air.", "Fog formation."], correctIndex: 2, explanation: "Mountain waves form when strong winds (≥ ~25-40 kt) blow roughly perpendicular to a ridge with stable air aloft: standing waves with rotor and severe turbulence on the lee side.", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_314", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "The lapse rate describes:", options: ["Temperature change with altitude.", "Pressure changes.", "Wind direction.", "Humidity variation."], correctIndex: 0, explanation: "The lapse rate is the rate of temperature decrease with an increase in altitude (standard: 2 °C / 3.5 °F per 1,000 ft); it determines atmospheric stability.", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_315", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Density altitude affects:", options: ["Navigation accuracy.", "Aircraft performance.", "Radio communication.", "Compass deviation."], correctIndex: 1, explanation: "Density altitude directly affects aircraft performance: high density altitude lengthens takeoff rolls, reduces climb rate, and decreases engine and propeller/thrust efficiency.", cite: "PHAK Cap. 11" },
  { id: "q_laof_3_316", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Frontal lifting occurs when:", options: ["Air cools overnight.", "Wind stops completely.", "Warm and cold air masses meet.", "Pressure is constant."], correctIndex: 2, explanation: "Frontal lifting occurs where air masses of different temperature and density meet: the warm air is forced aloft over the colder, denser air, producing clouds and precipitation.", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_317", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Which cloud is typically layered and stable?", options: ["Stratus.", "Cumulonimbus.", "Cumulus.", "Towering cumulus."], correctIndex: 0, explanation: "Stratus clouds are layered (stratiform), typical of stable air, associated with drizzle, low ceilings and poor visibility; cumuliform clouds indicate instability.", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_318", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Convective turbulence is strongest in:", options: ["Stable air.", "Clear skies only.", "Rising warm air currents.", "High pressure systems."], correctIndex: 2, explanation: "Convective turbulence comes from thermals — rising currents of heated air — strongest on sunny afternoons over unevenly heated terrain.", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_319", fuente: LA_OFICIAL_FUENTE, materia: "meteorologia", tema: "MET", text: "Dew point is:", options: ["Wind speed.", "Pressure altitude.", "Temperature at which air becomes saturated.", "Cloud base height."], correctIndex: 2, explanation: "Dew point is the temperature to which air must be cooled to become saturated (100% relative humidity); a small temperature/dew point spread warns of fog and low clouds.", cite: "PHAK Cap. 12" },
  { id: "q_laof_3_320", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Variation is difference between:", options: ["IAS and TAS.", "True north and magnetic north.", "Heading and track.", "GPS and VOR."], correctIndex: 1, explanation: "Variation is the angular difference between true north and magnetic north; it is applied to convert true courses/headings into magnetic ('East is least, West is best').", cite: "PHAK Cap. 16 (Navigation)" },
  { id: "q_laof_3_321", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Deviation is caused by:", options: ["Wind drift.", "Satellite error.", "Compass interference.", "Altimeter setting."], correctIndex: 2, explanation: "Deviation is the compass error induced by magnetic fields from the aircraft structure and electrical equipment; it is corrected with the compass card after swinging the compass.", cite: "PHAK Cap. 8 y 16" },
  { id: "q_laof_3_322", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Groundspeed is:", options: ["IAS reading.", "TAS only.", "Stall speed.", "Speed over earth surface."], correctIndex: 3, explanation: "Groundspeed is the aircraft's actual speed over the earth's surface: TAS corrected for the wind component (headwind reduces it, tailwind increases it).", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_323", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "DME gives:", options: ["Slant-range distance.", "Bearing.", "Wind speed.", "Heading correction."], correctIndex: 0, explanation: "DME measures slant-range distance in NM between aircraft and station, not horizontal distance; the error is greatest directly over the station (reads altitude in NM).", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_324", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "VOR radials extend:", options: ["Outward from station.", "Toward station only.", "Around airport only.", "Vertically upward."], correctIndex: 0, explanation: "The 360 VOR radials radiate outward FROM the station, referenced to magnetic north; a radial is identified by its outbound bearing.", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_325", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "GPS navigation uses:", options: ["Ground radar only.", "ADF signals only.", "Satellite signals.", "Localizer beams only."], correctIndex: 2, explanation: "GPS navigation is based on satellite signals: a minimum of 4 satellites yields a 3D position; RAIM adds integrity verification.", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_326", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Localizer provides:", options: ["Vertical guidance.", "Lateral guidance.", "Distance only.", "Wind correction."], correctIndex: 1, explanation: "The ILS localizer provides lateral course guidance (alignment with the runway centerline); vertical guidance comes from the glide slope.", cite: "PHAK Cap. 16; Instrument Flying Handbook" },
  { id: "q_laof_3_327", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Glide slope provides:", options: ["Horizontal guidance.", "Compass heading.", "Vertical descent guidance.", "DME arc distance."], correctIndex: 2, explanation: "The glide slope provides the vertical descent guidance of the ILS, typically a 3° path to the touchdown zone.", cite: "PHAK Cap. 16; Instrument Flying Handbook" },
  { id: "q_laof_3_328", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "RAIM relates to:", options: ["Engine monitoring.", "Fuel pressure.", "Radio tuning.", "GPS integrity."], correctIndex: 3, explanation: "RAIM (Receiver Autonomous Integrity Monitoring) verifies the integrity of GPS signals; it needs 5 satellites in view (or 4 plus baro-aiding) to detect a faulty satellite.", cite: "PHAK Cap. 16 (RAIM, 16-32)" },
  { id: "q_laof_3_329", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "ADF points to:", options: ["NDB bearing source.", "VOR radial.", "GPS waypoint only.", "Runway centerline."], correctIndex: 0, explanation: "The ADF needle points directly to the tuned NDB station, giving relative bearing to the station.", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_330", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "True course corrected for wind becomes:", options: ["Magnetic variation.", "Track.", "Heading.", "Groundspeed."], correctIndex: 2, explanation: "In the wind triangle, true course corrected for wind (applying the wind correction angle) gives true heading — the direction the nose must point so the resulting track matches the desired course.", cite: "PHAK Cap. 16 (wind triangle)" },
  { id: "q_laof_3_331", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Magnetic heading is:", options: ["IAS corrected for wind.", "Groundspeed direction.", "True heading corrected for variation.", "GPS track."], correctIndex: 2, explanation: "Magnetic heading is true heading corrected for magnetic variation; applying compass deviation then yields compass heading (TH ± VAR = MH; MH ± DEV = CH).", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_332", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Drift angle is:", options: ["Wind correction angle.", "Compass error.", "Altitude change.", "Speed variation."], correctIndex: 0, explanation: "Drift angle is the angle between heading and track caused by wind; in magnitude it corresponds to the wind correction angle applied to compensate it. The remaining options (compass error, altitude, speed) are unrelated to drift.", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_333", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "RNAV allows:", options: ["Only ground-based navigation.", "Visual navigation only.", "Flexible routing independent of ground stations.", "Only VOR tracking."], correctIndex: 2, explanation: "RNAV permits point-to-point flight on any desired path within coverage of station-referenced signals or aircraft self-contained systems, without overflying ground navaids.", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_334", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Holding pattern inbound leg timing is:", options: ["Always 30 seconds.", "Based on fuel only.", "Always 2 minutes.", "Typically 1 minute below 14,000 ft."], correctIndex: 3, explanation: "The standard holding pattern inbound leg is timed at 1 minute at or below 14,000 ft MSL (1.5 minutes above 14,000 ft).", cite: "AIM 5-3-8; Instrument Flying Handbook" },
  { id: "q_laof_3_335", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Standard rate turn is:", options: ["3° per second.", "1° per second.", "5° per second.", "10° per second."], correctIndex: 0, explanation: "A standard rate turn is 3° per second (360° in 2 minutes), as indicated by the turn coordinator's standard-rate index.", cite: "PHAK Cap. 8 (Flight Instruments)" },
  { id: "q_laof_3_336", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Crosswind component affects:", options: ["Fuel consumption only.", "Altimeter setting.", "Aircraft drift and runway alignment.", "Engine thrust."], correctIndex: 2, explanation: "The crosswind component causes lateral drift and complicates alignment with the runway centerline on takeoff and landing; aircraft also have a maximum demonstrated crosswind component.", cite: "PHAK Cap. 11; Airplane Flying Handbook" },
  { id: "q_laof_3_337", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "A back course approach uses:", options: ["Reverse sensing on localizer.", "Glide slope.", "GPS only.", "DME arc."], correctIndex: 0, explanation: "On a localizer back course, a conventional CDI shows reverse sensing (corrections are flown away from the needle) unless an HSI is set to the front-course inbound course.", cite: "Instrument Flying Handbook; AIM" },
  { id: "q_laof_3_338", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "MDA stands for:", options: ["Maximum descent angle.", "Minimum deviation altitude.", "Minimum descent altitude.", "Maximum drift altitude."], correctIndex: 2, explanation: "MDA = Minimum Descent Altitude: the lowest altitude on a non-precision approach below which descent is not authorized without the required visual references.", cite: "Instrument Flying Handbook; Pilot/Controller Glossary" },
  { id: "q_laof_3_339", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "DA is used in:", options: ["Non-precision approaches.", "Precision approaches.", "Visual approaches.", "VFR only."], correctIndex: 1, explanation: "DA (Decision Altitude) is used on precision approaches (ILS) and approaches with vertical guidance: upon reaching DA the pilot decides to continue visually or execute the missed approach. Non-precision approaches use MDA.", cite: "Instrument Flying Handbook; Pilot/Controller Glossary" },
  { id: "q_laof_3_340", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Track differs from heading because:", options: ["Heading ignores wind.", "Track includes wind correction.", "Track is always magnetic.", "Heading is ground-based."], correctIndex: 1, explanation: "Heading is where the nose points; track is the path actually described over the ground, which already reflects the wind effect — their difference is the drift angle. La opción A ('heading ignores wind') es ambigua porque el heading precisamente se ajusta para compensar el viento; la lectura pretendida del banco (consistente con su pregunta previa curso+viento=heading) es que el track incorpora la corrección/efecto del viento.", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_341", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Intercepting a radial requires:", options: ["Flying parallel.", "Maintaining heading only.", "Selecting appropriate intercept angle.", "Ignoring wind."], correctIndex: 2, explanation: "Intercepting a radial requires selecting an appropriate intercept angle toward the desired course (typically 30°-90° depending on distance and geometry), then leading the turn onto the course.", cite: "Instrument Flying Handbook" },
  { id: "q_laof_3_342", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Dead reckoning uses:", options: ["Time, speed, distance.", "GPS only.", "Satellite data.", "Radar vectors."], correctIndex: 0, explanation: "Dead reckoning is navigation computed from time, speed, distance, and direction flown from a known position, without external references.", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_343", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "INS navigation is based on:", options: ["Gyros and accelerometers.", "Ground stations.", "GPS only.", "VOR signals."], correctIndex: 0, explanation: "INS is self-contained: it integrates accelerations sensed by accelerometers on a gyro-stabilized (or ring-laser) reference to compute position, without external signals.", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_344", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "A waypoint is:", options: ["Airport only.", "Runway threshold.", "Defined geographic position.", "Radio frequency."], correctIndex: 2, explanation: "A waypoint is a predetermined geographical position (defined by coordinates or radial/distance) used for route definition and progress reporting in RNAV.", cite: "Pilot/Controller Glossary; PHAK Cap. 16" },
  { id: "q_laof_3_345", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Course deviation indicator shows:", options: ["Speed.", "Vertical speed.", "Engine thrust.", "Lateral deviation from course."], correctIndex: 3, explanation: "The CDI displays lateral deviation from the selected course in dots; with GPS the full-scale sensitivity varies by flight phase.", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_346", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Holding entries include:", options: ["Direct, teardrop, parallel.", "Left, right only.", "Climb and descend.", "Visual only."], correctIndex: 0, explanation: "The three standard holding pattern entries are direct, teardrop, and parallel, chosen according to the arrival sector (70°/110° divisions).", cite: "AIM 5-3-8; Instrument Flying Handbook" },
  { id: "q_laof_3_347", fuente: LA_OFICIAL_FUENTE, materia: "navegacion", tema: "IFR", text: "Flight management systems integrate:", options: ["Only VOR.", "Only GPS.", "Only INS.", "Multiple navigation sources."], correctIndex: 3, explanation: "The FMS integrates multiple navigation sources (GPS, IRS/INS, VOR/DME) plus air data and performance databases to compute the best navigation and performance solution.", cite: "PHAK Cap. 16" },
  { id: "q_laof_3_348", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "First action after engine failure after takeoff:", options: ["Maintain aircraft control.", "Call cabin crew.", "Dump fuel.", "Declare emergency immediately."], correctIndex: 0, explanation: "After an engine failure after takeoff, the first action is to maintain aircraft control: pitch for a safe airspeed and directional control ('aviate'). Solo después se navega, se comunica y se ejecutan los procedimientos.", cite: "Airplane Flying Handbook; doctrina Aviate-Navigate-Communicate" },
  { id: "q_laof_3_349", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Basic emergency priority is:", options: ["Communicate-Navigate-Aviate.", "Navigate-Communicate-Aviate.", "Aviate-Navigate-Communicate.", "Diagnose first."], correctIndex: 2, explanation: "The universal emergency priority is Aviate-Navigate-Communicate: first fly the airplane, then navigate it, and only then communicate. La comunicación nunca antecede al control del avión.", cite: "PHAK Cap. 2 (Aeronautical Decision-Making); doctrina FAA" },
  { id: "q_laof_3_350", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "In cockpit smoke event:", options: ["Ignore if no flames.", "Descend without coordination.", "Use checklist immediately.", "Shut all engines down immediately."], correctIndex: 2, explanation: "Smoke/fumes in the cockpit demands immediate execution of the applicable checklist (oxygen masks/goggles, crew communications, source isolation). Improvised drastic actions (shutting down all engines) or ignoring the smoke are unacceptable.", cite: "QRH/SOP de transporte aéreo; FAA AC 120-80 (in-flight fire)" },
  { id: "q_laof_3_351", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Pressurization loss first requires:", options: ["Extend gear.", "Reduce flaps.", "Turn off radios.", "Don oxygen masks."], correctIndex: 3, explanation: "In a pressurization loss the first memory item is donning oxygen masks: time of useful consciousness at FL350+ is only 30-60 seconds. The emergency descent follows once the crew is protected.", cite: "QRH memory items; PHAK Cap. 17 (hipoxia y TUC)" },
  { id: "q_laof_3_352", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Emergency descent purpose:", options: ["Burn fuel quickly.", "Reach breathable altitude rapidly", "Reduce engine wear.", "Avoid ATC delays."], correctIndex: 1, explanation: "The purpose of the emergency descent is to reach a breathable altitude (10,000 ft or MEA) as rapidly as possible after a depressurization, minimizing hypoxia exposure.", cite: "SOP de transporte aéreo; PHAK Cap. 17" },
  { id: "q_laof_3_353", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Unreliable airspeed procedure depends on:", options: ["Outside view only.", "Pitch and power known settings.", "Passenger reports.", "Groundspeed only."], correctIndex: 1, explanation: "With unreliable airspeed (pitot-static failure), the crew flies known pitch attitudes and power settings from the manufacturer's tables to guarantee safe performance while troubleshooting.", cite: "QRH Unreliable Airspeed / Airspeed Unreliable; doctrina pitch + power" },
  { id: "q_laof_3_354", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Bird strike may cause:", options: ["Engine or structural damage.", "Only cosmetic damage.", "No performance effect ever.", "GPS failure only."], correctIndex: 0, explanation: "A bird strike can cause engine damage/failure (ingestion) and structural damage (windshield, radome, leading edges); it requires performance assessment and the applicable checklist.", cite: "Doctrina operacional; requisitos de certificación de ingestión de aves" },
  { id: "q_laof_3_355", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Hydraulic failure may affect:", options: ["Controls, brakes, landing gear.", "Cabin lights only.", "Oxygen masks only.", "Weather radar only."], correctIndex: 0, explanation: "Hydraulic systems power flight controls, brakes, landing gear, spoilers, and nosewheel steering; their failure degrades multiple functions and may require alternate gear extension.", cite: "PHAK Cap. 7 (Aircraft Systems); QRH" },
  { id: "q_laof_3_356", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Rapid depressurization includes:", options: ["Quiet cabin.", "Fuel leak.", "Instant engine shutdown.", "Sudden pressure loss and fogging."], correctIndex: 3, explanation: "Rapid depressurization is recognized by a loud noise, sudden cabin pressure loss, condensation fog, flying dust, and cold; masks on and emergency descent follow.", cite: "PHAK Cap. 17; doctrina de presurización" },
  { id: "q_laof_3_357", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Wind shear escape maneuver requires:", options: ["Idle thrust.", "Descend immediately.", "Gear extension first.", "Maximum performance climb guidance."], correctIndex: 3, explanation: "The windshear escape maneuver requires maximum thrust and following the flight director windshear guidance in a maximum-performance climb, without changing configuration (gear/flaps) until clear of the shear.", cite: "FAA Windshear Training Aid; SOP windshear escape" },
  { id: "q_laof_3_358", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "First indication of engine fire requires:", options: ["Cabin announcement first.", "ATC clearance first.", "Memory items execution.", "Immediate landing only."], correctIndex: 2, explanation: "A confirmed engine fire triggers the memory items (thrust lever idle, fuel control cutoff, fire handle/agent discharge), followed by the checklist and the diversion/landing decision. Announcements and clearances never precede the immediate actions.", cite: "QRH memory items; SOP de transporte aéreo" },
  { id: "q_laof_3_359", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Smoke removal priority is:", options: ["Crew visibility and breathing.", "Passenger comfort.", "Cabin temperature.", "Lighting."], correctIndex: 0, explanation: "Smoke removal prioritizes restoring flight crew visibility and breathing so the crew can continue flying and land the aircraft; comfort, temperature, and lighting are secondary.", cite: "QRH Smoke Removal; FAA AC 120-80" },
  { id: "q_laof_3_360", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Hypoxia risk increases:", options: ["At high altitude without oxygen.", "At low altitude.", "During taxi.", "During descent."], correctIndex: 0, explanation: "Hypoxia risk increases at high altitude without supplemental oxygen due to lower partial pressure of oxygen; above FL250 the time of useful consciousness falls to minutes or seconds.", cite: "PHAK Cap. 17 (Aeromedical Factors)" },
  { id: "q_laof_3_361", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "A rejected takeoff decision must consider:", options: ["Only speed.", "Aircraft performance and failure severity.", "Weather only.", "Fuel quantity only."], correctIndex: 1, explanation: "The rejected takeoff decision weighs speed relative to V1, available performance (runway remaining, brake energy), and failure severity: at high speed only serious failures (fire, engine failure, unsafe to fly) justify rejecting.", cite: "FAA Takeoff Safety Training Aid; concepto V1/RTO" },
  { id: "q_laof_3_362", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Brake overheating risk increases with:", options: ["Short taxi.", "Low speed.", "Tailwind only.", "Heavy braking after landing."], correctIndex: 3, explanation: "Heavy braking after landing (or a high-speed RTO) converts large kinetic energy into brake heat: risk of thermal fuse plug release, brake fire, and fade; cooling times must be observed.", cite: "Brake energy/performance; SOP de transporte aéreo" },
  { id: "q_laof_3_363", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Fuel leak requires:", options: ["Immediate shutdown always.", "Ignore unless visible.", "Only ATC notification.", "Monitoring and checklist action."], correctIndex: 3, explanation: "A suspected fuel leak requires monitoring fuel quantity/balance and executing the QRH fuel leak checklist (possible tank isolation or engine shutdown); it does not automatically mean immediate shutdown.", cite: "QRH Fuel Leak; doctrina operacional" },
  { id: "q_laof_3_364", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Electrical failure affects:", options: ["Only lighting.", "Only navigation.", "Multiple aircraft systems.", "Only communication."], correctIndex: 2, explanation: "An electrical failure can degrade multiple systems: instruments, avionics, fuel pumps, pressurization, and lighting; it is managed by checklist, load shedding, and essential power configuration.", cite: "PHAK Cap. 7; QRH electrical" },
  { id: "q_laof_3_365", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Stall recovery requires:", options: ["Increase angle of attack.", "Reduce angle of attack.", "Increase bank angle.", "Extend flaps immediately."], correctIndex: 1, explanation: "Stall recovery requires first and foremost reducing the angle of attack (nose-down pitch input) to reattach airflow; then roll wings level and adjust thrust. Pulling up or adding configuration deepens the stall.", cite: "PHAK Cap. 5; FAA AC 120-109A (Stall Prevention and Recovery)" },
  { id: "q_laof_3_366", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Fire triangle consists of:", options: ["Air, pressure, speed.", "Electricity, heat, drag.", "Fuel, wind, altitude.", "Fuel, oxygen, heat."], correctIndex: 3, explanation: "The fire triangle consists of fuel, oxygen, and heat (plus the chain reaction); removing any one of the three extinguishes the fire — the principle behind fuel shutoff and extinguishing agents.", cite: "PHAK Cap. 7; doctrina básica contra incendios" },
  { id: "q_laof_3_367", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Emergency landing preparation includes:", options: ["Cabin and crew coordination.", "No briefing.", "Turning off all systems.", "Ignoring checklist."], correctIndex: 0, explanation: "Emergency landing preparation includes flight deck-cabin coordination (NITS/TEST briefing: nature, intentions, time, special instructions), securing the cabin, and evacuation briefing.", cite: "SOP/CRM de transporte aéreo" },
  { id: "q_laof_3_368", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "TCAS RA requires:", options: ["Immediate compliance.", "ATC clearance first.", "Ignore if visual contact.", "Reduce speed."], correctIndex: 0, explanation: "A TCAS Resolution Advisory requires immediate compliance, even when contrary to the current ATC instruction: RAs are coordinated between the aircraft involved and delay in following them erodes separation.", cite: "ICAO Doc 8168 / Anexo 11 (ACAS); AIM 4-4-16" },
  { id: "q_laof_3_369", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "After RA, pilot should:", options: ["Ignore ATC.", "Return to clearance after conflict resolved.", "Descend immediately.", "Land immediately."], correctIndex: 1, explanation: "After 'clear of conflict', the pilot must promptly return to the current ATC clearance and notify ATC of the RA deviation.", cite: "Doctrina ACAS/TCAS; ICAO PANS-OPS; AIM 4-4-16" },
  { id: "q_laof_3_370", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Runaway trim requires:", options: ["Ignore system.", "Increase speed.", "Extend gear.", "Use memory items."], correctIndex: 3, explanation: "Runaway trim (runaway stabilizer) is a memory-item failure: grasp the control column, disconnect autopilot/electric trim, and use the stabilizer trim cutout switches; the checklist follows. Ignoring it can render the aircraft uncontrollable.", cite: "QRH memory items (Runaway Stabilizer); SOP" },
  { id: "q_laof_3_371", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Cabin depressurization requires:", options: ["Descent only.", "Communication first.", "Oxygen first, then descent.", "Checklist later."], correctIndex: 2, explanation: "Cabin depressurization requires oxygen first, then descent: without masks on, the crew loses useful consciousness (30-60 s at FL350) before completing the descent. Protected crew, then emergency descent to 10,000 ft/MEA.", cite: "QRH; PHAK Cap. 17 (TUC)" },
  { id: "q_laof_3_372", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Fire detection systems:", options: ["Are always false.", "Replace pilot judgment.", "Are optional.", "Provide early warning."], correctIndex: 3, explanation: "Fire detection systems provide early warning so the crew can act before a fire becomes uncontrollable; warnings are verified and acted upon, and the systems complement — not replace — pilot judgment.", cite: "PHAK Cap. 7; certificación de sistemas de detección de fuego" },
  { id: "q_laof_3_373", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Engine failure in cruise requires:", options: ["Immediate descent always.", "Shut down all engines.", "Performance assessment and checklist.", "Ignore warning."], correctIndex: 2, explanation: "An engine failure in cruise calls for securing the engine per checklist and assessing performance (driftdown to the one-engine-inoperative ceiling) before deciding the diversion; it does not automatically require an emergency descent.", cite: "QRH engine failure/driftdown; performance one-engine-inoperative" },
  { id: "q_laof_3_374", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "CRM helps by:", options: ["Reducing workload.", "Eliminating errors.", "Improving teamwork and decisions.", "Replacing SOPs."], correctIndex: 2, explanation: "CRM improves teamwork, communication, and decision-making by using all available resources (people, equipment, information); it does not eliminate error nor replace SOPs.", cite: "PHAK Cap. 2 (ADM/CRM); FAA AC 120-51" },
  { id: "q_laof_3_375", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Go-around decision should be made when:", options: ["Late touchdown.", "ATC delay.", "Unstable approach.", "Cabin request."], correctIndex: 2, explanation: "An unstable approach (outside stabilized-approach criteria of configuration, path, speed, and descent rate at the 1,000/500 ft gates) mandates a go-around: it is the primary defense against approach-and-landing accidents.", cite: "Flight Safety Foundation ALAR (stabilized approach criteria); SOP" },
  { id: "q_laof_3_376", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Emergency communication priority is:", options: ["Company first.", "Passengers first.", "Maintenance first.", "ATC and crew coordination."], correctIndex: 3, explanation: "In an emergency, communication priority goes to internal crew coordination and ATC (declare MAYDAY/PAN PAN, obtain priority handling); company and passengers are advised later, as workload permits.", cite: "Doctrina Aviate-Navigate-Communicate; SOP de emergencias" },
  { id: "q_laof_3_377", fuente: LA_OFICIAL_FUENTE, materia: "operaciones", tema: "OPS-EN", text: "Post-flight after emergency:", options: ["No report needed.", "Only verbal report.", "Follow reporting procedures.", "Ignore documentation."], correctIndex: 2, explanation: "After an emergency, reporting procedures must be followed: captain's report to the company and authority (mandatory occurrence/safety reports), plus maintenance documentation. Documentation supports the SMS and is legally required.", cite: "SOP/SMS; requisitos de reporte obligatorio de sucesos (autoridad aeronáutica)" },
];
